'use client';

import { useState, useCallback, useEffect, useRef } from 'react';
import { Navigation } from '@/components/layout/Navigation';
import { CyberpunkCanvas } from '@/components/canvas/CyberpunkCanvas';
import { useSimulationStore } from '@/store/simulation-store';
import { useSound } from '@/hooks/use-sound';
import { GridBackground } from '@/components/ui/GridBackground';
import { NeonCard, NeonPanel } from '@/components/ui/NeonCard';
import { CyberButton } from '@/components/ui/CyberButton';
import { StatusLED, StatusIndicator } from '@/components/ui/StatusLED';
import { NodeTooltip } from '@/components/tooltips/NodeTooltip';
import { DeviceInspector } from '@/components/inspector/DeviceInspector';
import { generateTooltipData } from '@/lib/device-data-generator';
import type { DeviceData, DeviceStatus } from '@/types/simulation-data';
import {
    DDoSIcon,
    SQLInjectionIcon,
    MalwareIcon,
    PhishingIcon,
    MITMIcon,
    DefenseFirewallIcon,
    BlockIPIcon,
    RateLimitIcon,
    DNSFilterIcon,
    QuarantineIcon,
    AttackSwordsIcon,
    DefenseShieldIcon,
    TerminalIcon,
    PlayIcon,
    PauseIcon,
    ResetIcon,
    HealthIcon,
} from '@/components/ui/CyberIcons';
import anime from 'animejs';

const ATTACK_TYPES = [
    { id: 'ddos', label: 'DDoS', Icon: DDoSIcon, description: 'Overwhelm with traffic', damage: 15, color: '#EF4444' },
    { id: 'sql', label: 'SQL Injection', Icon: SQLInjectionIcon, description: 'Database attack', damage: 20, color: '#F97316' },
    { id: 'malware', label: 'Malware', Icon: MalwareIcon, description: 'Deploy malware', damage: 25, color: '#DC2626' },
    { id: 'phishing', label: 'Phishing', Icon: PhishingIcon, description: 'Social engineering', damage: 12, color: '#FBBF24' },
    { id: 'mitm', label: 'MITM', Icon: MITMIcon, description: 'Intercept data', damage: 10, color: '#F472B6' },
];

const DEFENSE_TYPES = [
    { id: 'firewall', label: 'Firewall', Icon: DefenseFirewallIcon, color: '#22C55E', heal: 10 },
    { id: 'block', label: 'Block IP', Icon: BlockIPIcon, color: '#EF4444', heal: 8 },
    { id: 'rate', label: 'Rate Limit', Icon: RateLimitIcon, color: '#F59E0B', heal: 12 },
    { id: 'dns', label: 'DNS Filter', Icon: DNSFilterIcon, color: '#3B82F6', heal: 15 },
    { id: 'quarantine', label: 'Quarantine', Icon: QuarantineIcon, color: '#8B5CF6', heal: 20 },
];

interface LogEntry {
    id: string;
    timestamp: string;
    type: 'info' | 'attack' | 'defense' | 'error';
    message: string;
    color: string;
}

export default function SandboxPage() {
    const {
        networkHealth,
        damageNetwork,
        healNetwork,
        logs,
        clearLogs,
        addLog,
        setEntities,
        addConnection,
        clearEntities,
        clearConnections,
        clearPackets,
        entities,
        hoveredNodeId,
        inspectorOpen,
        inspectorData,
        closeInspector,
    } = useSimulationStore();
    const { playAttack, playDefense, playSuccess, playError } = useSound();

    const [isPlaying, setIsPlaying] = useState(false);
    const [speed, setSpeed] = useState(1);
    const [systemLogs, setSystemLogs] = useState<LogEntry[]>([]);
    const [tooltipPos, setTooltipPos] = useState({ x: 0, y: 0 });
    const logContainerRef = useRef<HTMLDivElement>(null);

    // Initialize network topology
    useEffect(() => {
        clearEntities();
        clearConnections();
        clearPackets();

        setTimeout(() => {
            const entities = new Map();

            entities.set('user-pc', {
                id: 'user-pc',
                type: 'PC',
                position: { x: -350, y: 0 },
                status: 'active',
                metadata: { label: 'USER PC', ip: '192.168.1.10' }
            });

            entities.set('router', {
                id: 'router',
                type: 'Router',
                position: { x: -150, y: 0 },
                status: 'active',
                metadata: { label: 'ROUTER', ip: '192.168.1.1' }
            });

            entities.set('dns-server', {
                id: 'dns-server',
                type: 'DNS',
                position: { x: -50, y: 150 },
                status: 'active',
                metadata: { label: 'DNS SERVER', ip: '8.8.8.8' }
            });

            entities.set('firewall', {
                id: 'firewall',
                type: 'Firewall',
                position: { x: 50, y: -80 },
                status: 'active',
                metadata: { label: 'FIREWALL' }
            });

            entities.set('web-server', {
                id: 'web-server',
                type: 'Server',
                position: { x: 180, y: 0 },
                status: 'active',
                metadata: { label: 'WEB SERVER', ip: '10.0.0.5' }
            });

            entities.set('attacker', {
                id: 'attacker',
                type: 'Attacker',
                position: { x: 350, y: 0 },
                status: 'idle',
                metadata: { label: 'ATTACKER', ip: '45.5.5.166' }
            });

            setEntities(entities);

            setTimeout(() => {
                addConnection({ id: 'conn-1', sourceId: 'user-pc', targetId: 'router', style: 'solid', status: 'active', protocol: 'DHCP' });
                addConnection({ id: 'conn-2', sourceId: 'router', targetId: 'dns-server', style: 'dotted', status: 'active', protocol: 'DNS' });
                addConnection({ id: 'conn-3', sourceId: 'router', targetId: 'firewall', style: 'solid', status: 'active' });
                addConnection({ id: 'conn-4', sourceId: 'firewall', targetId: 'web-server', style: 'encrypted', status: 'active', protocol: 'HTTP' });
                addConnection({ id: 'conn-attack', sourceId: 'attacker', targetId: 'firewall', style: 'blocked', status: 'idle' });
            }, 200);
        }, 100);

        addSystemLog('info', 'System initialized. Network topology loaded.', '#22D3EE');
        addSystemLog('info', 'DHCP Request from User PC', '#22D3EE');
        addSystemLog('info', 'DHCP | Status: OK', '#22C55E');

        return () => { clearEntities(); };
    }, []);

    const addSystemLog = useCallback((type: LogEntry['type'], message: string, color: string) => {
        const timestamp = new Date().toLocaleTimeString('en-US', { hour12: false });
        const id = `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
        setSystemLogs(prev => [...prev.slice(-20), { id, timestamp, type, message, color }]);
    }, []);

    useEffect(() => {
        if (logContainerRef.current) {
            logContainerRef.current.scrollTop = logContainerRef.current.scrollHeight;
        }
    }, [systemLogs]);

    const handleAttack = useCallback((attack: typeof ATTACK_TYPES[0], buttonRef: HTMLButtonElement | null) => {
        playAttack(attack.id as 'ddos' | 'sql' | 'phishing' | 'malware');
        damageNetwork(attack.damage);

        // Vibrate animation on button
        if (buttonRef) {
            anime({
                targets: buttonRef,
                translateX: [0, -3, 3, -3, 3, 0],
                duration: 300,
                easing: 'easeInOutSine',
            });
        }

        addSystemLog('attack', `[!] ${attack.label} Attack Initiated`, attack.color);
        addSystemLog('attack', `Targeting: Web Server (10.0.0.5)`, attack.color);
        addLog({ type: 'attack', message: `${attack.label} attack launched!`, protocol: 'ATTACK' });

        // Screen flash
        document.body.style.transition = 'background 0.2s';
        document.body.style.background = `${attack.color}15`;
        setTimeout(() => { document.body.style.background = ''; }, 300);

        if (networkHealth - attack.damage <= 0) {
            playError();
            addSystemLog('error', '[X] CRITICAL: Network Compromised!', '#EF4444');
        }
    }, [playAttack, damageNetwork, addLog, networkHealth, playError, addSystemLog]);

    const handleDefense = useCallback((defense: typeof DEFENSE_TYPES[0], buttonRef: HTMLButtonElement | null) => {
        playDefense();
        healNetwork(defense.heal);

        // Pulse animation on button
        if (buttonRef) {
            anime({
                targets: buttonRef,
                scale: [1, 1.05, 1],
                duration: 300,
                easing: 'easeOutExpo',
            });
        }

        addSystemLog('defense', `[+] ${defense.label} Activated`, defense.color);
        addSystemLog('info', `Defense Status: ACTIVE`, defense.color);
        addLog({ type: 'defense', message: `${defense.label} activated!`, protocol: 'DEFENSE' });

        document.body.style.transition = 'background 0.2s';
        document.body.style.background = `${defense.color}15`;
        setTimeout(() => { document.body.style.background = ''; }, 300);

        if (networkHealth + defense.heal >= 100) {
            playSuccess();
            addSystemLog('info', '[OK] Network Fully Secured', '#22C55E');
        }
    }, [playDefense, healNetwork, addLog, networkHealth, playSuccess, addSystemLog]);

    const resetNetwork = useCallback(() => {
        healNetwork(100);
        clearLogs();
        setSystemLogs([]);
        addSystemLog('info', '[R] Network Reset to Healthy State', '#22D3EE');
    }, [healNetwork, clearLogs, addSystemLog]);

    const healthColor = networkHealth > 70 ? '#22C55E' : networkHealth > 40 ? '#F59E0B' : '#EF4444';
    const healthStatus = networkHealth > 70 ? 'active' : networkHealth > 40 ? 'warning' : 'critical';

    return (
        <div className="min-h-screen flex flex-col" style={{ background: '#050A15' }}>
            <Navigation />

            <div className="flex-1 flex flex-col lg:flex-row">
                {/* Left Panel - Attack Tools */}
                <NeonPanel
                    variant="attack"
                    title="Attack Tools"
                    icon={<AttackSwordsIcon size="sm" glow />}
                    className="lg:w-52"
                >
                    <div className="flex flex-col gap-2">
                        {ATTACK_TYPES.map((attack) => (
                            <NeonCard
                                key={attack.id}
                                variant="attack"
                                className="p-2"
                                onClick={() => handleAttack(attack, null)}
                            >
                                <div className="flex items-center gap-3">
                                    <div
                                        className="p-2 rounded-lg"
                                        style={{ background: `${attack.color}20` }}
                                    >
                                        <attack.Icon size="md" glow glowIntensity={8} />
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="text-xs font-semibold" style={{ color: attack.color }}>
                                            {attack.label}
                                        </div>
                                        <div className="text-[10px] text-slate-500 truncate">
                                            DMG: {attack.damage}
                                        </div>
                                    </div>
                                </div>
                            </NeonCard>
                        ))}
                    </div>
                </NeonPanel>

                {/* Center - Canvas */}
                <div className="flex-1 flex flex-col">
                    {/* Top Controls */}
                    <div
                        className="flex items-center justify-center gap-4 py-3 px-4"
                        style={{
                            background: 'rgba(15, 23, 42, 0.8)',
                            borderBottom: '1px solid rgba(34, 211, 238, 0.15)'
                        }}
                    >
                        <CyberButton
                            variant={isPlaying ? 'defense' : 'neutral'}
                            size="sm"
                            icon={isPlaying ? <PauseIcon size="sm" /> : <PlayIcon size="sm" />}
                            onClick={() => setIsPlaying(!isPlaying)}
                        >
                            {isPlaying ? 'PAUSE' : 'PLAY'}
                        </CyberButton>

                        <div className="flex items-center gap-1">
                            {[1, 2, 4].map((s) => (
                                <CyberButton
                                    key={s}
                                    variant={speed === s ? 'primary' : 'ghost'}
                                    size="sm"
                                    onClick={() => setSpeed(s)}
                                >
                                    x{s}
                                </CyberButton>
                            ))}
                        </div>

                        <CyberButton
                            variant="neutral"
                            size="sm"
                            icon={<ResetIcon size="sm" />}
                            onClick={resetNetwork}
                        >
                            RESET
                        </CyberButton>
                    </div>

                    {/* Canvas Area */}
                    <GridBackground
                        className="flex-1 relative min-h-[400px]"
                        showGrid={true}
                        showParticles={true}
                        particleCount={15}
                    >
                        <CyberpunkCanvas onMousePositionChange={(x, y) => setTooltipPos({ x, y })} />

                        {/* Health Overlay */}
                        <div
                            className="absolute top-4 right-4 flex items-center gap-3 px-4 py-2 rounded-lg"
                            style={{
                                background: 'rgba(15, 23, 42, 0.9)',
                                border: `1px solid ${healthColor}40`,
                                backdropFilter: 'blur(8px)',
                            }}
                        >
                            <HealthIcon size="sm" color={healthColor} glow />
                            <span className="text-xs text-slate-400">NETWORK</span>
                            <div
                                className="w-24 h-2 rounded-full overflow-hidden"
                                style={{ background: 'rgba(30, 41, 59, 0.8)' }}
                            >
                                <div
                                    className="h-full rounded-full transition-all duration-500"
                                    style={{
                                        width: `${Math.max(0, Math.min(100, networkHealth))}%`,
                                        background: healthColor,
                                        boxShadow: `0 0 10px ${healthColor}`
                                    }}
                                />
                            </div>
                            <span className="text-sm font-bold" style={{ color: healthColor }}>
                                {Math.max(0, Math.min(100, networkHealth))}%
                            </span>
                            <StatusLED status={healthStatus} size="sm" />
                        </div>
                    </GridBackground>

                    {/* System Logs */}
                    <div
                        className="h-36"
                        style={{
                            background: 'rgba(0, 0, 0, 0.6)',
                            borderTop: '1px solid rgba(34, 211, 238, 0.15)'
                        }}
                    >
                        <div
                            className="flex items-center justify-between px-3 py-1.5"
                            style={{ borderBottom: '1px solid rgba(34, 211, 238, 0.1)' }}
                        >
                            <div className="flex items-center gap-2">
                                <TerminalIcon size="sm" color="#22D3EE" glow glowIntensity={5} />
                                <span className="text-xs font-bold text-slate-400 tracking-wider">SYSTEM LOGS</span>
                            </div>
                            <CyberButton variant="ghost" size="sm" onClick={() => setSystemLogs([])}>
                                Clear
                            </CyberButton>
                        </div>
                        <div
                            ref={logContainerRef}
                            className="h-[calc(100%-28px)] overflow-y-auto p-2 font-mono text-[11px]"
                            style={{ scrollBehavior: 'smooth' }}
                        >
                            {systemLogs.map((log) => (
                                <div key={log.id} className="flex gap-2 py-0.5">
                                    <span className="text-slate-600">[{log.timestamp}]</span>
                                    <span style={{ color: log.color }}>{log.message}</span>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                {/* Right Panel - Defense Controls */}
                <NeonPanel
                    variant="defense"
                    title="Defense Controls"
                    icon={<DefenseShieldIcon size="sm" glow />}
                    className="lg:w-52"
                >
                    <div className="flex flex-col gap-2">
                        {DEFENSE_TYPES.map((defense) => (
                            <NeonCard
                                key={defense.id}
                                variant="defense"
                                className="p-2"
                                onClick={() => handleDefense(defense, null)}
                            >
                                <div className="flex items-center gap-3">
                                    <div
                                        className="p-2 rounded-lg"
                                        style={{ background: `${defense.color}20` }}
                                    >
                                        <defense.Icon size="md" glow glowIntensity={8} />
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="text-xs font-semibold" style={{ color: defense.color }}>
                                            {defense.label}
                                        </div>
                                        <div className="text-[10px] text-slate-500 truncate">
                                            HEAL: +{defense.heal}
                                        </div>
                                    </div>
                                </div>
                            </NeonCard>
                        ))}
                    </div>
                </NeonPanel>
            </div>

            {/* Hover Tooltip */}
            <NodeTooltip
                visible={hoveredNodeId !== null}
                x={tooltipPos.x}
                y={tooltipPos.y}
                data={hoveredNodeId ? (() => {
                    const entity = entities.get(hoveredNodeId);
                    if (!entity) return null;
                    const status: DeviceStatus = entity.status === 'active' ? 'online'
                        : entity.status === 'compromised' ? 'compromised'
                            : entity.status === 'blocked' ? 'isolated'
                                : 'online';
                    return generateTooltipData(
                        entity.id,
                        entity.metadata?.label || entity.id,
                        entity.type,
                        entity.metadata?.ip || 'N/A',
                        status,
                        networkHealth
                    );
                })() : null}
            />

            {/* Device Inspector Panel */}
            <DeviceInspector
                open={inspectorOpen}
                onClose={closeInspector}
                device={inspectorData as DeviceData | null}
            />
        </div>
    );
}

'use client';

import { useEffect, useRef, useCallback, useState } from 'react';
import { useSimulationStore } from '@/store/simulation-store';
import { NetworkEntity, ENTITY_VISUALS } from '@/types/entities';
import { Connection } from '@/types/connections';
import { generateDeviceData } from '@/lib/device-data-generator';
import type { DeviceStatus } from '@/types/simulation-data';

// ===== CYBERPUNK COLOR PALETTE =====
const CYBER_COLORS = {
    bg: '#050A15',
    grid: '#0D1929',
    gridLine: 'rgba(34, 211, 238, 0.08)',
    node: {
        pc: '#22D3EE',
        router: '#8B5CF6',
        dns: '#A855F7',
        firewall: '#F59E0B',
        server: '#22C55E',
        attacker: '#EF4444',
        cloud: '#3B82F6'
    },
    connection: {
        normal: '#3B82F6',
        active: '#22D3EE',
        encrypted: '#22C55E',
        attack: '#EF4444',
        blocked: '#F97316'
    }
};

// ===== PROTOCOL LABELS =====
const PROTOCOL_COLORS: Record<string, string> = {
    'DHCP': '#FACC15',
    'DNS': '#A855F7',
    'HTTP': '#22D3EE',
    'HTTPS': '#22C55E',
    'TCP': '#3B82F6',
    'ATTACK': '#EF4444',
    'MALWARE': '#DC2626'
};

// Props interface for external mouse position callback
interface CyberpunkCanvasProps {
    onMousePositionChange?: (x: number, y: number) => void;
}

export function CyberpunkCanvas({ onMousePositionChange }: CyberpunkCanvasProps = {}) {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const animationFrameRef = useRef<number>(0);
    const timeRef = useRef<number>(0);

    const {
        entities,
        connections,
        viewport,
        setViewportOffset,
        setDragging,
        networkHealth,
        hoveredNodeId,
        setHoveredNode,
        openInspector,
    } = useSimulationStore();

    // Mouse drag state
    const dragStartRef = useRef<{ x: number; y: number; offsetX: number; offsetY: number } | null>(null);
    const [isHoveringNode, setIsHoveringNode] = useState(false);

    // Handle resize with ResizeObserver for proper initial sizing
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const parent = canvas.parentElement;
        if (!parent) return;

        const updateCanvasSize = () => {
            const dpr = window.devicePixelRatio || 1;
            const width = parent.clientWidth;
            const height = parent.clientHeight;

            // Only update if we have valid dimensions
            if (width > 0 && height > 0) {
                canvas.width = width * dpr;
                canvas.height = height * dpr;
                canvas.style.width = `${width}px`;
                canvas.style.height = `${height}px`;
                const ctx = canvas.getContext('2d');
                if (ctx) ctx.scale(dpr, dpr);
            }
        };

        // Use ResizeObserver to detect when parent has valid dimensions
        const resizeObserver = new ResizeObserver((entries) => {
            for (const entry of entries) {
                if (entry.contentRect.width > 0 && entry.contentRect.height > 0) {
                    updateCanvasSize();
                }
            }
        });

        resizeObserver.observe(parent);

        // Also handle window resize for DPR changes
        window.addEventListener('resize', updateCanvasSize);

        // Initial size update
        updateCanvasSize();

        return () => {
            resizeObserver.disconnect();
            window.removeEventListener('resize', updateCanvasSize);
        };
    }, []);

    // Node hit detection
    const findNodeAtPosition = useCallback((screenX: number, screenY: number): NetworkEntity | null => {
        const canvas = canvasRef.current;
        if (!canvas) return null;

        const rect = canvas.getBoundingClientRect();
        const dpr = window.devicePixelRatio || 1;
        const width = canvas.width / dpr;
        const height = canvas.height / dpr;

        // Convert screen coords to canvas coords (accounting for viewport offset)
        const canvasX = (screenX - rect.left) - viewport.offsetX - width / 2;
        const canvasY = (screenY - rect.top) - viewport.offsetY - height / 2;

        const NODE_RADIUS = 40; // Hit area radius

        for (const [id, entity] of entities) {
            const dx = canvasX - entity.position.x;
            const dy = canvasY - entity.position.y;
            const distance = Math.sqrt(dx * dx + dy * dy);

            if (distance <= NODE_RADIUS) {
                return entity;
            }
        }
        return null;
    }, [entities, viewport]);

    // Mouse handlers
    const handleMouseDown = useCallback((e: React.MouseEvent) => {
        // Only start dragging if not clicking on a node
        const node = findNodeAtPosition(e.clientX, e.clientY);
        if (node) return; // Don't drag when clicking nodes

        dragStartRef.current = {
            x: e.clientX, y: e.clientY,
            offsetX: viewport.offsetX, offsetY: viewport.offsetY
        };
        setDragging(true);
    }, [viewport, setDragging, findNodeAtPosition]);

    const handleMouseMove = useCallback((e: React.MouseEvent) => {
        // Update external position callback
        onMousePositionChange?.(e.clientX, e.clientY);

        // Check for node hover
        const node = findNodeAtPosition(e.clientX, e.clientY);
        if (node) {
            if (hoveredNodeId !== node.id) {
                setHoveredNode(node.id);
            }
            setIsHoveringNode(true);
        } else {
            if (hoveredNodeId !== null) {
                setHoveredNode(null);
            }
            setIsHoveringNode(false);
        }

        // Handle dragging
        if (!dragStartRef.current) return;
        const dx = e.clientX - dragStartRef.current.x;
        const dy = e.clientY - dragStartRef.current.y;
        setViewportOffset(dragStartRef.current.offsetX + dx, dragStartRef.current.offsetY + dy);
    }, [setViewportOffset, findNodeAtPosition, hoveredNodeId, setHoveredNode, onMousePositionChange]);

    const handleMouseUp = useCallback(() => {
        dragStartRef.current = null;
        setDragging(false);
    }, [setDragging]);

    const handleMouseLeave = useCallback(() => {
        dragStartRef.current = null;
        setDragging(false);
        setHoveredNode(null);
        setIsHoveringNode(false);
    }, [setDragging, setHoveredNode]);

    const handleClick = useCallback((e: React.MouseEvent) => {
        const node = findNodeAtPosition(e.clientX, e.clientY);
        if (node) {
            // Generate full device data and open inspector
            const status: DeviceStatus = node.status === 'active' ? 'online'
                : node.status === 'compromised' ? 'under_attack'
                    : node.status === 'blocked' ? 'isolated'
                        : 'online';

            const deviceData = generateDeviceData(
                node.id,
                node.metadata?.label || node.id,
                node.type,
                node.metadata?.ip || '192.168.1.1',
                status,
                networkHealth
            );
            openInspector('device', deviceData);
        }
    }, [findNodeAtPosition, networkHealth, openInspector]);

    // ===== MAIN RENDER LOOP =====
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let running = true;

        const render = (timestamp: number) => {
            if (!running) return;
            timeRef.current = timestamp / 1000;

            const dpr = window.devicePixelRatio || 1;
            const width = canvas.width / dpr;
            const height = canvas.height / dpr;

            // Clear
            ctx.fillStyle = CYBER_COLORS.bg;
            ctx.fillRect(0, 0, width, height);

            ctx.save();
            ctx.translate(viewport.offsetX + width / 2, viewport.offsetY + height / 2);

            // Draw grid
            drawCyberGrid(ctx, width, height, viewport.offsetX, viewport.offsetY, timeRef.current);

            // Draw connections
            connections.forEach((conn) => {
                const source = entities.get(conn.sourceId);
                const target = entities.get(conn.targetId);
                if (source && target) {
                    drawCyberConnection(ctx, conn, source, target, timeRef.current);
                }
            });

            // Draw entities
            entities.forEach((entity) => {
                drawCyberNode(ctx, entity, timeRef.current);
            });

            ctx.restore();

            animationFrameRef.current = requestAnimationFrame(render);
        };

        animationFrameRef.current = requestAnimationFrame(render);
        return () => {
            running = false;
            cancelAnimationFrame(animationFrameRef.current);
        };
    }, [entities, connections, viewport, networkHealth]);

    return (
        <div className="relative w-full h-full overflow-hidden">
            <canvas
                ref={canvasRef}
                className={`absolute inset-0 ${isHoveringNode ? 'cursor-pointer' : 'cursor-grab active:cursor-grabbing'}`}
                onMouseDown={handleMouseDown}
                onMouseMove={handleMouseMove}
                onMouseUp={handleMouseUp}
                onMouseLeave={handleMouseLeave}
                onClick={handleClick}
            />
        </div>
    );
}

// ===== GRID RENDERER =====
function drawCyberGrid(
    ctx: CanvasRenderingContext2D,
    width: number, height: number,
    offsetX: number, offsetY: number,
    time: number
) {
    const gridSize = 40;
    const startX = -width - (offsetX % gridSize);
    const startY = -height - (offsetY % gridSize);

    // Grid lines
    ctx.strokeStyle = CYBER_COLORS.gridLine;
    ctx.lineWidth = 1;

    for (let x = startX; x < width; x += gridSize) {
        ctx.beginPath();
        ctx.moveTo(x, -height);
        ctx.lineTo(x, height);
        ctx.stroke();
    }
    for (let y = startY; y < height; y += gridSize) {
        ctx.beginPath();
        ctx.moveTo(-width, y);
        ctx.lineTo(width, y);
        ctx.stroke();
    }

    // Scanning line effect
    const scanY = Math.sin(time * 0.3) * height * 0.8;
    const gradient = ctx.createLinearGradient(0, scanY - 20, 0, scanY + 20);
    gradient.addColorStop(0, 'rgba(34, 211, 238, 0)');
    gradient.addColorStop(0.5, 'rgba(34, 211, 238, 0.1)');
    gradient.addColorStop(1, 'rgba(34, 211, 238, 0)');
    ctx.fillStyle = gradient;
    ctx.fillRect(-width, scanY - 20, width * 2, 40);
}

// ===== NODE RENDERER =====
function drawCyberNode(
    ctx: CanvasRenderingContext2D,
    entity: NetworkEntity,
    time: number
) {
    const { x, y } = entity.position;
    const color = CYBER_COLORS.node[entity.type.toLowerCase() as keyof typeof CYBER_COLORS.node] || '#3B82F6';

    const boxWidth = 70;
    const boxHeight = 60;
    const iconSize = 24;

    ctx.save();

    // Outer glow
    const glowIntensity = 0.3 + Math.sin(time * 2 + x * 0.01) * 0.1;
    ctx.shadowColor = color;
    ctx.shadowBlur = 20 * glowIntensity;

    // Main box
    const gradient = ctx.createLinearGradient(x, y - boxHeight / 2, x, y + boxHeight / 2);
    gradient.addColorStop(0, `${color}30`);
    gradient.addColorStop(0.5, `${color}15`);
    gradient.addColorStop(1, `${color}05`);

    ctx.fillStyle = gradient;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;

    // Draw rounded rectangle
    ctx.beginPath();
    ctx.roundRect(x - boxWidth / 2, y - boxHeight / 2, boxWidth, boxHeight, 8);
    ctx.fill();
    ctx.stroke();

    ctx.shadowBlur = 0;

    // Icon
    ctx.save();
    ctx.translate(x, y - 10);
    drawNodeIcon(ctx, entity.type, iconSize, color);
    ctx.restore();

    // Label
    ctx.font = 'bold 10px "Inter", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#FFFFFF';
    ctx.fillText(entity.metadata.label || entity.type, x, y + 22);

    // IP badge below
    if (entity.metadata.ip) {
        ctx.font = '9px "JetBrains Mono", monospace';
        ctx.fillStyle = color;
        ctx.fillText(`IP: ${entity.metadata.ip}`, x, y + 34);
    }

    // Status indicator (top-right corner)
    const statusColors: Record<string, string> = {
        active: '#22C55E',
        idle: '#64748B',
        under_attack: '#EF4444',
        compromised: '#DC2626',
        blocked: '#F97316'
    };
    const statusColor = statusColors[entity.status] || '#64748B';

    ctx.fillStyle = statusColor;
    ctx.shadowColor = statusColor;
    ctx.shadowBlur = 8;
    ctx.beginPath();
    ctx.arc(x + boxWidth / 2 - 8, y - boxHeight / 2 + 8, 4, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;

    ctx.restore();
}

// ===== NODE ICON RENDERER =====
function drawNodeIcon(ctx: CanvasRenderingContext2D, type: string, size: number, color: string) {
    ctx.strokeStyle = color;
    ctx.fillStyle = color;
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    const s = size / 2;

    switch (type) {
        case 'PC':
            // Monitor
            ctx.strokeRect(-s * 0.7, -s * 0.4, s * 1.4, s * 0.8);
            ctx.beginPath();
            ctx.moveTo(-s * 0.2, s * 0.4);
            ctx.lineTo(s * 0.2, s * 0.4);
            ctx.lineTo(s * 0.15, s * 0.6);
            ctx.lineTo(-s * 0.15, s * 0.6);
            ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(-s * 0.35, s * 0.6);
            ctx.lineTo(s * 0.35, s * 0.6);
            ctx.stroke();
            break;

        case 'Router':
            ctx.strokeRect(-s * 0.6, -s * 0.2, s * 1.2, s * 0.4);
            // Antennas
            ctx.beginPath();
            ctx.moveTo(-s * 0.35, -s * 0.2);
            ctx.lineTo(-s * 0.45, -s * 0.5);
            ctx.moveTo(s * 0.35, -s * 0.2);
            ctx.lineTo(s * 0.45, -s * 0.5);
            ctx.stroke();
            // LEDs
            for (let i = -2; i <= 2; i++) {
                ctx.beginPath();
                ctx.arc(i * s * 0.2, 0, 2, 0, Math.PI * 2);
                ctx.fill();
            }
            break;

        case 'Firewall':
            // Shield shape
            ctx.beginPath();
            ctx.moveTo(0, -s * 0.5);
            ctx.lineTo(s * 0.4, -s * 0.3);
            ctx.lineTo(s * 0.4, s * 0.1);
            ctx.quadraticCurveTo(s * 0.2, s * 0.4, 0, s * 0.55);
            ctx.quadraticCurveTo(-s * 0.2, s * 0.4, -s * 0.4, s * 0.1);
            ctx.lineTo(-s * 0.4, -s * 0.3);
            ctx.closePath();
            ctx.stroke();
            // Flame
            ctx.beginPath();
            ctx.moveTo(0, s * 0.2);
            ctx.quadraticCurveTo(s * 0.1, 0, 0, -s * 0.15);
            ctx.quadraticCurveTo(-s * 0.1, 0, 0, s * 0.2);
            ctx.fill();
            break;

        case 'DNS':
            // Database cylinder
            ctx.beginPath();
            ctx.ellipse(0, -s * 0.3, s * 0.4, s * 0.15, 0, 0, Math.PI * 2);
            ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(-s * 0.4, -s * 0.3);
            ctx.lineTo(-s * 0.4, s * 0.3);
            ctx.ellipse(0, s * 0.3, s * 0.4, s * 0.15, 0, Math.PI, 0, true);
            ctx.lineTo(s * 0.4, -s * 0.3);
            ctx.stroke();
            break;

        case 'Server':
            // Stacked boxes
            for (let i = 0; i < 3; i++) {
                const ly = -s * 0.4 + i * s * 0.35;
                ctx.strokeRect(-s * 0.5, ly, s * 1, s * 0.3);
                ctx.beginPath();
                ctx.arc(s * 0.3, ly + s * 0.15, 2, 0, Math.PI * 2);
                ctx.fill();
            }
            break;

        case 'Attacker':
            // Skull/danger
            ctx.beginPath();
            ctx.moveTo(0, -s * 0.5);
            ctx.lineTo(s * 0.45, s * 0.4);
            ctx.lineTo(-s * 0.45, s * 0.4);
            ctx.closePath();
            ctx.stroke();
            ctx.font = `bold ${s * 0.6}px sans-serif`;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('!', 0, s * 0.1);
            break;

        default:
            ctx.beginPath();
            ctx.arc(0, 0, s * 0.4, 0, Math.PI * 2);
            ctx.stroke();
    }
}

// ===== CONNECTION RENDERER =====
function drawCyberConnection(
    ctx: CanvasRenderingContext2D,
    conn: Connection,
    source: NetworkEntity,
    target: NetworkEntity,
    time: number
) {
    const x1 = source.position.x;
    const y1 = source.position.y;
    const x2 = target.position.x;
    const y2 = target.position.y;

    const dx = x2 - x1;
    const dy = y2 - y1;
    const length = Math.sqrt(dx * dx + dy * dy);
    const angle = Math.atan2(dy, dx);

    // Offset from node edges
    const offset = 45;
    const startX = x1 + Math.cos(angle) * offset;
    const startY = y1 + Math.sin(angle) * offset;
    const endX = x2 - Math.cos(angle) * offset;
    const endY = y2 - Math.sin(angle) * offset;

    // Determine color
    let color = CYBER_COLORS.connection.normal;
    if (conn.style === 'encrypted') color = CYBER_COLORS.connection.encrypted;
    else if (conn.style === 'pulsing') color = CYBER_COLORS.connection.attack;
    else if (conn.style === 'blocked') color = CYBER_COLORS.connection.blocked;
    else if (conn.status === 'active') color = CYBER_COLORS.connection.active;

    ctx.save();

    // Glow
    ctx.strokeStyle = color;
    ctx.lineWidth = 6;
    ctx.globalAlpha = 0.2;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(startX, startY);
    ctx.lineTo(endX, endY);
    ctx.stroke();

    // Main line
    ctx.globalAlpha = 0.8;
    ctx.lineWidth = 2;

    if (conn.style === 'blocked') {
        ctx.setLineDash([6, 4]);
        ctx.globalAlpha = 0.5;
    } else if (conn.style === 'dotted') {
        ctx.setLineDash([4, 4]);
        ctx.lineDashOffset = -time * 20;
    }

    ctx.beginPath();
    ctx.moveTo(startX, startY);
    ctx.lineTo(endX, endY);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.globalAlpha = 1;

    // Animated particles
    if (conn.status === 'active' || conn.style === 'encrypted') {
        const particleCount = 3;
        for (let i = 0; i < particleCount; i++) {
            const progress = ((time * 0.4) + (i / particleCount)) % 1;
            const px = startX + (endX - startX) * progress;
            const py = startY + (endY - startY) * progress;

            ctx.fillStyle = color;
            ctx.globalAlpha = 0.8;
            ctx.beginPath();
            ctx.arc(px, py, 4, 0, Math.PI * 2);
            ctx.fill();

            ctx.fillStyle = '#FFFFFF';
            ctx.globalAlpha = 1;
            ctx.beginPath();
            ctx.arc(px, py, 2, 0, Math.PI * 2);
            ctx.fill();
        }
    }

    // Protocol label
    if (conn.protocol) {
        const midX = (startX + endX) / 2;
        const midY = (startY + endY) / 2 - 12;
        const protocolColor = PROTOCOL_COLORS[conn.protocol] || color;

        ctx.font = 'bold 9px "JetBrains Mono", monospace';
        const textWidth = ctx.measureText(conn.protocol).width + 12;

        // Badge background
        ctx.fillStyle = 'rgba(15, 23, 42, 0.9)';
        ctx.strokeStyle = protocolColor;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.roundRect(midX - textWidth / 2, midY - 8, textWidth, 16, 3);
        ctx.fill();
        ctx.stroke();

        // Arrow
        ctx.fillStyle = protocolColor;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(`${conn.protocol}ΓåÆ`, midX, midY);
    }

    // Arrowhead at end
    if (conn.status === 'active') {
        const arrowSize = 10;
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.moveTo(endX, endY);
        ctx.lineTo(
            endX - arrowSize * Math.cos(angle - Math.PI / 6),
            endY - arrowSize * Math.sin(angle - Math.PI / 6)
        );
        ctx.lineTo(
            endX - arrowSize * Math.cos(angle + Math.PI / 6),
            endY - arrowSize * Math.sin(angle + Math.PI / 6)
        );
        ctx.closePath();
        ctx.fill();
    }

    ctx.restore();
}

'use client';

import { useSimulationStore } from '@/store/simulation-store';
import { useState, useEffect, useRef, useMemo } from 'react';
import { NetworkEntity } from '@/types/entities';

interface TooltipState {
    visible: boolean;
    x: number;
    y: number;
    entity: NetworkEntity | null;
}

export function EntityTooltip() {
    const { entities, viewport } = useSimulationStore();
    const [tooltip, setTooltip] = useState<TooltipState>({
        visible: false,
        x: 0,
        y: 0,
        entity: null
    });
    const tooltipRef = useRef<HTMLDivElement>(null);
    const hideTimeoutRef = useRef<NodeJS.Timeout | null>(null);

    // Listen for mouse movements over the canvas
    useEffect(() => {
        const canvas = document.querySelector('canvas');
        if (!canvas) return;

        const handleMouseMove = (e: MouseEvent) => {
            const rect = canvas.getBoundingClientRect();
            const mouseX = e.clientX - rect.left - rect.width / 2 - viewport.offsetX;
            const mouseY = e.clientY - rect.top - rect.height / 2 - viewport.offsetY;

            // Check if mouse is near any entity
            let foundEntity: NetworkEntity | null = null;
            let minDistance = 60; // Hover radius

            entities.forEach((entity) => {
                const dx = mouseX - entity.position.x;
                const dy = mouseY - entity.position.y;
                const distance = Math.sqrt(dx * dx + dy * dy);

                if (distance < minDistance) {
                    minDistance = distance;
                    foundEntity = entity;
                }
            });

            if (foundEntity) {
                // Clear hide timeout
                if (hideTimeoutRef.current) {
                    clearTimeout(hideTimeoutRef.current);
                    hideTimeoutRef.current = null;
                }

                setTooltip({
                    visible: true,
                    x: e.clientX + 15,
                    y: e.clientY - 10,
                    entity: foundEntity
                });
            } else if (tooltip.visible) {
                // Delay hiding tooltip
                if (!hideTimeoutRef.current) {
                    hideTimeoutRef.current = setTimeout(() => {
                        setTooltip(prev => ({ ...prev, visible: false }));
                        hideTimeoutRef.current = null;
                    }, 200);
                }
            }
        };

        const handleMouseLeave = () => {
            hideTimeoutRef.current = setTimeout(() => {
                setTooltip(prev => ({ ...prev, visible: false }));
            }, 100);
        };

        canvas.addEventListener('mousemove', handleMouseMove);
        canvas.addEventListener('mouseleave', handleMouseLeave);

        return () => {
            canvas.removeEventListener('mousemove', handleMouseMove);
            canvas.removeEventListener('mouseleave', handleMouseLeave);
            if (hideTimeoutRef.current) {
                clearTimeout(hideTimeoutRef.current);
            }
        };
    }, [entities, viewport, tooltip.visible]);

    // Get status color
    const getStatusColor = (status: string) => {
        const colors: Record<string, string> = {
            idle: '#64748B',
            active: '#22C55E',
            under_attack: '#EF4444',
            blocked: '#F97316',
            connecting: '#22D3EE',
            processing: '#8B5CF6',
            overloaded: '#FBBF24',
            compromised: '#DC2626'
        };
        return colors[status] || '#64748B';
    };

    if (!tooltip.visible || !tooltip.entity) return null;

    const entity = tooltip.entity;

    return (
        <div
            ref={tooltipRef}
            className="fixed z-50 pointer-events-none transition-opacity duration-150"
            style={{
                left: tooltip.x,
                top: tooltip.y,
                opacity: tooltip.visible ? 1 : 0
            }}
        >
            <div
                className="rounded-lg p-3 shadow-xl backdrop-blur-sm"
                style={{
                    background: 'rgba(15, 23, 42, 0.95)',
                    border: '1px solid rgba(34, 211, 238, 0.3)',
                    minWidth: '180px'
                }}
            >
                {/* Header */}
                <div className="flex items-center gap-2 mb-2 pb-2 border-b border-slate-700">
                    <span className="text-lg">
                        {entity.type === 'PC' && ''}
                        {entity.type === 'Router' && ''}
                        {entity.type === 'Server' && ''}
                        {entity.type === 'DNS' && ''}
                        {entity.type === 'ISP' && ''}
                        {entity.type === 'Firewall' && ''}
                        {entity.type === 'Attacker' && ''}
                        {entity.type === 'Cloud' && ''}
                    </span>
                    <div>
                        <p className="text-sm font-semibold text-white">
                            {entity.metadata.label || entity.type}
                        </p>
                        <p className="text-[10px] uppercase tracking-wider text-slate-400">
                            {entity.type}
                        </p>
                    </div>
                </div>

                {/* Details */}
                <div className="space-y-1.5 text-[11px]">
                    {/* IP Address */}
                    {entity.metadata.ip && (
                        <div className="flex items-center justify-between">
                            <span className="text-slate-400">IP Address:</span>
                            <span className="font-mono text-cyan-400">{entity.metadata.ip}</span>
                        </div>
                    )}

                    {/* Hostname */}
                    {entity.metadata.hostname && (
                        <div className="flex items-center justify-between">
                            <span className="text-slate-400">Hostname:</span>
                            <span className="font-mono text-slate-300">{entity.metadata.hostname}</span>
                        </div>
                    )}

                    {/* Status */}
                    <div className="flex items-center justify-between">
                        <span className="text-slate-400">Status:</span>
                        <span
                            className="px-1.5 py-0.5 rounded text-[10px] font-bold uppercase"
                            style={{
                                background: `${getStatusColor(entity.status)}20`,
                                color: getStatusColor(entity.status)
                            }}
                        >
                            {entity.status.replace('_', ' ')}
                        </span>
                    </div>

                    {/* Protocol if available */}
                    {entity.metadata.protocol && (
                        <div className="flex items-center justify-between">
                            <span className="text-slate-400">Protocol:</span>
                            <span className="text-purple-400">{entity.metadata.protocol}</span>
                        </div>
                    )}

                    {/* Ports if available */}
                    {entity.metadata.ports && entity.metadata.ports.length > 0 && (
                        <div className="flex items-center justify-between">
                            <span className="text-slate-400">Ports:</span>
                            <span className="text-blue-400 font-mono">
                                {entity.metadata.ports.slice(0, 3).join(', ')}
                                {entity.metadata.ports.length > 3 && '...'}
                            </span>
                        </div>
                    )}

                    {/* Health if available */}
                    {entity.health !== undefined && (
                        <div className="mt-2 pt-2 border-t border-slate-700">
                            <div className="flex items-center justify-between mb-1">
                                <span className="text-slate-400">Health:</span>
                                <span style={{ color: entity.health > 50 ? '#22C55E' : '#EF4444' }}>
                                    {entity.health}%
                                </span>
                            </div>
                            <div className="w-full h-1.5 bg-slate-700 rounded-full overflow-hidden">
                                <div
                                    className="h-full rounded-full transition-all"
                                    style={{
                                        width: `${entity.health}%`,
                                        background: entity.health > 70
                                            ? '#22C55E'
                                            : entity.health > 40
                                                ? '#FBBF24'
                                                : '#EF4444'
                                    }}
                                />
                            </div>
                        </div>
                    )}
                </div>

                {/* Footer hint */}
                <div className="mt-2 pt-2 border-t border-slate-700 text-[9px] text-slate-500 text-center">
                    Click to inspect | ID: {entity.id}
                </div>
            </div>
        </div>
    );
}

'use client';

import { useEffect, useRef, useCallback, useMemo } from 'react';
import { useSimulationStore } from '@/store/simulation-store';
import { drawGrid, drawAttackZone } from './renderers/GridRenderer';
import { drawEntity, updateEntityTime } from './renderers/EntityRenderer';
import { drawConnection, updateConnectionTime } from './renderers/ConnectionRenderer';
import { drawPacket, ENHANCED_PACKET_SPEEDS } from './renderers/PacketRenderer';

// Local packet state for smooth animation (not in React state)
interface LocalPacket {
    id: string;
    connectionId: string;
    protocol: string;
    progress: number;
    speed: number;
    direction: 'forward' | 'reverse';
}

export function SimulationCanvas() {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const animationFrameRef = useRef<number>(0);
    const lastTimeRef = useRef<number>(0);
    const localPacketsRef = useRef<Map<string, LocalPacket>>(new Map());
    const fpsRef = useRef<{ frames: number; lastTime: number; fps: number }>({
        frames: 0,
        lastTime: performance.now(),
        fps: 60
    });

    const {
        entities,
        connections,
        packets,
        viewport,
        setViewportOffset,
        setDragging,
        isPlaying,
        isPaused,
        playbackSpeed,
        networkHealth,
        addLog,
        highlightedEntityId,
        highlightedConnectionId
    } = useSimulationStore();

    // Determine if system is under attack based on entity states
    const isUnderAttack = useMemo(() => {
        return Array.from(entities.values()).some(
            e => e.status === 'under_attack' || e.status === 'compromised'
        );
    }, [entities]);

    // Sync React packets to local ref (only when packets array changes)
    useEffect(() => {
        const localPackets = localPacketsRef.current;
        const reactPacketIds = new Set(packets.map(p => p.id));

        // Add new packets
        packets.forEach(p => {
            if (!localPackets.has(p.id)) {
                const speed = ENHANCED_PACKET_SPEEDS[p.protocol] || ENHANCED_PACKET_SPEEDS.DEFAULT;
                localPackets.set(p.id, {
                    id: p.id,
                    connectionId: p.connectionId,
                    protocol: p.protocol,
                    progress: p.progress,
                    speed: speed,
                    direction: p.direction
                });
            }
        });

        // Remove deleted packets
        localPackets.forEach((_, id) => {
            if (!reactPacketIds.has(id)) {
                localPackets.delete(id);
            }
        });
    }, [packets]);

    // Mouse drag state
    const dragStartRef = useRef<{ x: number; y: number; offsetX: number; offsetY: number } | null>(null);

    // Handle resize with debouncing for performance
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        let resizeTimeout: NodeJS.Timeout;

        const handleResize = () => {
            clearTimeout(resizeTimeout);
            resizeTimeout = setTimeout(() => {
                const parent = canvas.parentElement;
                if (parent) {
                    const dpr = window.devicePixelRatio || 1;
                    canvas.width = parent.clientWidth * dpr;
                    canvas.height = parent.clientHeight * dpr;
                    canvas.style.width = `${parent.clientWidth}px`;
                    canvas.style.height = `${parent.clientHeight}px`;

                    const ctx = canvas.getContext('2d');
                    if (ctx) {
                        ctx.scale(dpr, dpr);
                    }
                }
            }, 100);
        };

        // Initial sizing
        const parent = canvas.parentElement;
        if (parent) {
            const dpr = window.devicePixelRatio || 1;
            canvas.width = parent.clientWidth * dpr;
            canvas.height = parent.clientHeight * dpr;
            canvas.style.width = `${parent.clientWidth}px`;
            canvas.style.height = `${parent.clientHeight}px`;

            const ctx = canvas.getContext('2d');
            if (ctx) {
                ctx.scale(dpr, dpr);
            }
        }

        window.addEventListener('resize', handleResize);
        return () => {
            window.removeEventListener('resize', handleResize);
            clearTimeout(resizeTimeout);
        };
    }, []);

    // Mouse handlers for panning
    const handleMouseDown = useCallback((e: React.MouseEvent) => {
        dragStartRef.current = {
            x: e.clientX,
            y: e.clientY,
            offsetX: viewport.offsetX,
            offsetY: viewport.offsetY
        };
        setDragging(true);
    }, [viewport.offsetX, viewport.offsetY, setDragging]);

    const handleMouseMove = useCallback((e: React.MouseEvent) => {
        if (!dragStartRef.current) return;

        const dx = e.clientX - dragStartRef.current.x;
        const dy = e.clientY - dragStartRef.current.y;

        setViewportOffset(
            dragStartRef.current.offsetX + dx,
            dragStartRef.current.offsetY + dy
        );
    }, [setViewportOffset]);

    const handleMouseUp = useCallback(() => {
        dragStartRef.current = null;
        setDragging(false);
    }, [setDragging]);

    // Handle node click for inspection
    const handleClick = useCallback((e: React.MouseEvent) => {
        if (dragStartRef.current) return;

        const canvas = canvasRef.current;
        if (!canvas) return;

        const rect = canvas.getBoundingClientRect();
        const x = e.clientX - rect.left - rect.width / 2 - viewport.offsetX;
        const y = e.clientY - rect.top - rect.height / 2 - viewport.offsetY;

        // Check if click hit any entity (with larger hit area for better UX)
        entities.forEach((entity) => {
            const dx = x - entity.position.x;
            const dy = y - entity.position.y;
            const distance = Math.sqrt(dx * dx + dy * dy);

            if (distance < 55) {
                // Entity clicked - show detailed info
                addLog({
                    type: 'info',
                    message: `∩┐╜ Inspecting: ${entity.metadata.label || entity.type}`,
                    entityId: entity.id,
                    protocol: entity.type
                });

                if (entity.metadata.ip) {
                    addLog({
                        type: 'info',
                        message: `   IP: ${entity.metadata.ip} | Status: ${entity.status.toUpperCase()}`,
                        entityId: entity.id
                    });
                }
            }
        });
    }, [entities, viewport, addLog]);

    // ============================================
    // OPTIMIZED RENDER LOOP
    // ============================================

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;

        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let running = true;
        lastTimeRef.current = performance.now();

        const render = (timestamp: number) => {
            if (!running) return;

            // Calculate delta time with frame cap
            const deltaTime = Math.min(timestamp - lastTimeRef.current, 50);
            lastTimeRef.current = timestamp;

            // FPS tracking
            fpsRef.current.frames++;
            if (timestamp - fpsRef.current.lastTime >= 1000) {
                fpsRef.current.fps = fpsRef.current.frames;
                fpsRef.current.frames = 0;
                fpsRef.current.lastTime = timestamp;
            }

            // Update animation times
            updateConnectionTime();
            updateEntityTime();

            const dpr = window.devicePixelRatio || 1;
            const width = canvas.width / dpr;
            const height = canvas.height / dpr;

            // ============================================
            // BACKGROUND LAYER
            // ============================================

            ctx.fillStyle = '#0A0F1A';
            ctx.fillRect(0, 0, width, height);

            // Save context and apply viewport transform
            ctx.save();
            ctx.translate(viewport.offsetX + width / 2, viewport.offsetY + height / 2);

            // Draw grid with health-based coloring
            drawGrid(ctx, width, height, viewport.offsetX, viewport.offsetY, networkHealth, isUnderAttack);

            // ============================================
            // ATTACK ZONES (under entities)
            // ============================================

            // Draw attack indicators around attacked nodes
            entities.forEach((entity) => {
                if (entity.status === 'under_attack' || entity.status === 'compromised') {
                    drawAttackZone(ctx, entity.position.x, entity.position.y, 120);
                }
            });

            // ============================================
            // CONNECTION LAYER
            // ============================================

            connections.forEach((connection) => {
                const source = entities.get(connection.sourceId);
                const target = entities.get(connection.targetId);
                if (source && target) {
                    const isHighlighted = connection.id === highlightedConnectionId;
                    drawConnection(ctx, connection, source.position, target.position, undefined, isHighlighted);
                }
            });

            // ============================================
            // ENTITY LAYER
            // ============================================

            entities.forEach((entity) => {
                const isHighlighted = entity.id === highlightedEntityId;
                drawEntity(ctx, entity, isHighlighted);
            });

            // ============================================
            // PACKET LAYER (top)
            // ============================================

            const localPackets = localPacketsRef.current;
            const packetsToRemove: string[] = [];

            localPackets.forEach((packet) => {
                const connection = connections.get(packet.connectionId);
                if (!connection) {
                    packetsToRemove.push(packet.id);
                    return;
                }

                const source = entities.get(connection.sourceId);
                const target = entities.get(connection.targetId);
                if (!source || !target) {
                    packetsToRemove.push(packet.id);
                    return;
                }

                // Update packet progress (smooth animation independent of React)
                if (isPlaying && !isPaused) {
                    packet.progress += packet.speed * playbackSpeed * deltaTime / 16;
                }

                if (packet.progress >= 1) {
                    packetsToRemove.push(packet.id);
                } else {
                    drawPacket(ctx, packet, source.position, target.position);
                }
            });

            // Batch remove completed packets
            packetsToRemove.forEach(id => localPackets.delete(id));

            ctx.restore();

            // Request next frame
            animationFrameRef.current = requestAnimationFrame(render);
        };

        animationFrameRef.current = requestAnimationFrame(render);

        return () => {
            running = false;
            if (animationFrameRef.current) {
                cancelAnimationFrame(animationFrameRef.current);
            }
        };
    }, [entities, connections, viewport, isPlaying, isPaused, playbackSpeed, networkHealth, isUnderAttack, highlightedEntityId, highlightedConnectionId]);

    return (
        <canvas
            ref={canvasRef}
            className="absolute inset-0 cursor-grab active:cursor-grabbing"
            onMouseDown={handleMouseDown}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onMouseLeave={handleMouseUp}
            onClick={handleClick}
        />
    );
}

// Enhanced Connection renderer with visual traffic feedback
// Direction arrows, encryption shimmer, congestion, attack pulses

import { Connection, CONNECTION_VISUALS } from '@/types/connections';
import { Position } from '@/types/entities';

// Animation time (synced globally)
let globalTime = 0;

export function updateConnectionTime() {
    globalTime = Date.now() / 1000;
}

export function drawConnection(
    ctx: CanvasRenderingContext2D,
    connection: Connection,
    sourcePos: Position,
    targetPos: Position,
    activeProtocol?: string,
    isHighlighted: boolean = false
) {
    const visual = CONNECTION_VISUALS[connection.style];

    ctx.save();

    const dx = targetPos.x - sourcePos.x;
    const dy = targetPos.y - sourcePos.y;
    const length = Math.sqrt(dx * dx + dy * dy);
    const angle = Math.atan2(dy, dx);

    // Offset from entity centers to edges
    const offsetStart = 55;
    const offsetEnd = 55;

    const startX = sourcePos.x + Math.cos(angle) * offsetStart;
    const startY = sourcePos.y + Math.sin(angle) * offsetStart;
    const endX = targetPos.x - Math.cos(angle) * offsetEnd;
    const endY = targetPos.y - Math.sin(angle) * offsetEnd;

    // Determine line style based on connection type
    let lineColor = visual.color;
    let glowColor = visual.color;
    let lineWidth = visual.strokeWidth * (connection.bandwidth || 1);

    // ============================================
    // STYLE-BASED COLORING
    // ============================================

    if (connection.style === 'encrypted') {
        lineColor = '#22C55E';
        glowColor = '#22C55E';
    } else if (connection.style === 'pulsing') {
        lineColor = '#EF4444';
        glowColor = '#EF4444';
        // Attack connections are thicker
        lineWidth = visual.strokeWidth * 1.5;
    } else if (connection.style === 'blocked') {
        lineColor = '#F97316';
        glowColor = '#F97316';
    }

    // ============================================
    // HIGHLIGHT EFFECT (for log linking)
    // ============================================

    if (isHighlighted) {
        ctx.strokeStyle = '#FACC15';
        ctx.lineWidth = lineWidth + 8;
        ctx.globalAlpha = 0.3;
        ctx.lineCap = 'round';
        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.stroke();
        ctx.globalAlpha = 1;
    }

    // ============================================
    // GLOW LAYER
    // ============================================

    // Base glow
    ctx.strokeStyle = glowColor;
    ctx.lineWidth = lineWidth + 6;
    ctx.globalAlpha = 0.15;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(startX, startY);
    ctx.lineTo(endX, endY);
    ctx.stroke();

    // Extra glow for attack connections with pulsing
    if (connection.style === 'pulsing') {
        const pulse = 0.2 + Math.sin(globalTime * 6) * 0.15;
        ctx.lineWidth = lineWidth + 14;
        ctx.globalAlpha = pulse;
        ctx.stroke();

        // Draw attack pulse waves
        drawAttackPulseWaves(ctx, startX, startY, endX, endY, lineColor);
    }

    // Encrypted shimmer effect
    if (connection.style === 'encrypted') {
        drawEncryptionShimmer(ctx, startX, startY, endX, endY);
    }

    ctx.globalAlpha = 1;

    // ============================================
    // MAIN LINE
    // ============================================

    const gradient = ctx.createLinearGradient(startX, startY, endX, endY);
    gradient.addColorStop(0, lineColor);
    gradient.addColorStop(0.5, lineColor);
    gradient.addColorStop(1, lineColor);

    ctx.strokeStyle = gradient;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = 'round';

    // Blocked connections are dashed and faded
    if (connection.style === 'blocked') {
        ctx.setLineDash([8, 6]);
        ctx.globalAlpha = 0.5;
    } else if (visual.dashArray) {
        const dashValues = visual.dashArray.split(',').map(Number);
        ctx.setLineDash(dashValues);
        ctx.lineDashOffset = -globalTime * 30 * visual.animationSpeed;
    }

    ctx.beginPath();
    ctx.moveTo(startX, startY);
    ctx.lineTo(endX, endY);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.globalAlpha = 1;

    // ============================================
    // TRAFFIC DIRECTION INDICATORS
    // ============================================

    if (connection.status === 'active' || connection.style === 'encrypted' || connection.style === 'pulsing') {
        drawDirectionalFlow(ctx, startX, startY, endX, endY, lineColor, connection.style === 'pulsing');
    }

    // ============================================
    // ARROWHEAD
    // ============================================

    if (connection.status === 'active' || connection.status === 'attack') {
        drawArrowhead(ctx, startX, startY, endX, endY, lineColor);
    }

    // ============================================
    // PROTOCOL LABEL BADGE
    // ============================================

    if (activeProtocol || connection.style === 'encrypted' || connection.style === 'pulsing') {
        const label = activeProtocol || (connection.style === 'encrypted' ? 'HTTPS' : 'ATTACK');
        const badgeColor = connection.style === 'pulsing' ? '#EF4444' : lineColor;
        drawProtocolBadge(ctx, (startX + endX) / 2, (startY + endY) / 2 - 12, label, badgeColor);
    }

    // ============================================
    // CONGESTION INDICATOR
    // ============================================

    if (connection.bandwidth && connection.bandwidth > 1.5) {
        drawCongestionEffect(ctx, startX, startY, endX, endY, connection.bandwidth);
    }

    ctx.restore();
}

// ============================================
// EFFECT RENDERERS
// ============================================

function drawDirectionalFlow(
    ctx: CanvasRenderingContext2D,
    x1: number, y1: number,
    x2: number, y2: number,
    color: string,
    isAttack: boolean = false
) {
    const particleCount = isAttack ? 6 : 4;
    const speed = isAttack ? 0.6 : 0.4;
    const size = isAttack ? 5 : 4;

    for (let i = 0; i < particleCount; i++) {
        const offset = (i / particleCount);
        const progress = ((globalTime * speed) + offset) % 1;

        const x = x1 + (x2 - x1) * progress;
        const y = y1 + (y2 - y1) * progress;

        // Outer glow
        ctx.fillStyle = color;
        ctx.globalAlpha = isAttack ? 0.5 : 0.4;
        ctx.beginPath();
        ctx.arc(x, y, size + 2, 0, Math.PI * 2);
        ctx.fill();

        // Core
        ctx.fillStyle = '#FFFFFF';
        ctx.globalAlpha = isAttack ? 0.95 : 0.9;
        ctx.beginPath();
        ctx.arc(x, y, size / 2, 0, Math.PI * 2);
        ctx.fill();
    }

    ctx.globalAlpha = 1;
}

function drawEncryptionShimmer(
    ctx: CanvasRenderingContext2D,
    x1: number, y1: number,
    x2: number, y2: number
) {
    const shimmerPos = (globalTime * 0.3) % 1;
    const shimmerWidth = 40;

    const dx = x2 - x1;
    const dy = y2 - y1;
    const length = Math.sqrt(dx * dx + dy * dy);

    // Calculate shimmer center position along line
    const shimmerX = x1 + dx * shimmerPos;
    const shimmerY = y1 + dy * shimmerPos;

    // Draw shimmer gradient perpendicular to line
    const gradient = ctx.createRadialGradient(
        shimmerX, shimmerY, 0,
        shimmerX, shimmerY, shimmerWidth
    );
    gradient.addColorStop(0, 'rgba(34, 197, 94, 0.4)');
    gradient.addColorStop(0.5, 'rgba(34, 197, 94, 0.1)');
    gradient.addColorStop(1, 'rgba(34, 197, 94, 0)');

    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(shimmerX, shimmerY, shimmerWidth, 0, Math.PI * 2);
    ctx.fill();

    // Lock icon at center of encrypted connection
    const centerX = (x1 + x2) / 2;
    const centerY = (y1 + y2) / 2;

    ctx.fillStyle = '#22C55E';
    ctx.globalAlpha = 0.8;
    ctx.font = 'bold 12px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('', centerX, centerY + 14);
    ctx.globalAlpha = 1;
}

function drawAttackPulseWaves(
    ctx: CanvasRenderingContext2D,
    x1: number, y1: number,
    x2: number, y2: number,
    color: string
) {
    const waveCount = 3;
    const waveSpeed = 0.8;

    for (let i = 0; i < waveCount; i++) {
        const offset = i / waveCount;
        const progress = ((globalTime * waveSpeed) + offset) % 1;

        const x = x1 + (x2 - x1) * progress;
        const y = y1 + (y2 - y1) * progress;

        // Expanding ring
        const ringSize = 8 + (1 - progress) * 12;
        const alpha = progress * 0.4;

        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.globalAlpha = alpha;
        ctx.beginPath();
        ctx.arc(x, y, ringSize, 0, Math.PI * 2);
        ctx.stroke();
    }

    ctx.globalAlpha = 1;
}

function drawCongestionEffect(
    ctx: CanvasRenderingContext2D,
    x1: number, y1: number,
    x2: number, y2: number,
    bandwidth: number
) {
    // Add vibration effect for congested lines
    const vibration = Math.sin(globalTime * 20) * (bandwidth - 1) * 2;
    const angle = Math.atan2(y2 - y1, x2 - x1) + Math.PI / 2;

    const offsetX = Math.cos(angle) * vibration;
    const offsetY = Math.sin(angle) * vibration;

    // Draw congestion indicator dots
    const centerX = (x1 + x2) / 2 + offsetX;
    const centerY = (y1 + y2) / 2 + offsetY;

    ctx.fillStyle = '#FBBF24';
    ctx.globalAlpha = 0.6;
    ctx.beginPath();
    ctx.arc(centerX, centerY, 3, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;
}

function drawArrowhead(
    ctx: CanvasRenderingContext2D,
    fromX: number, fromY: number,
    toX: number, toY: number,
    color: string
) {
    const angle = Math.atan2(toY - fromY, toX - fromX);
    const headLength = 14;

    // Position arrowhead at 80% along the line
    const arrowX = fromX + (toX - fromX) * 0.8;
    const arrowY = fromY + (toY - fromY) * 0.8;

    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(arrowX + headLength * Math.cos(angle), arrowY + headLength * Math.sin(angle));
    ctx.lineTo(
        arrowX - headLength * 0.6 * Math.cos(angle - Math.PI / 5),
        arrowY - headLength * 0.6 * Math.sin(angle - Math.PI / 5)
    );
    ctx.lineTo(
        arrowX - headLength * 0.6 * Math.cos(angle + Math.PI / 5),
        arrowY - headLength * 0.6 * Math.sin(angle + Math.PI / 5)
    );
    ctx.closePath();
    ctx.fill();
}

function drawProtocolBadge(
    ctx: CanvasRenderingContext2D,
    x: number, y: number,
    label: string,
    color: string
) {
    ctx.font = 'bold 10px monospace';
    const textWidth = ctx.measureText(label).width;
    const padding = 6;
    const height = 18;
    const width = textWidth + padding * 2;

    // Badge shadow
    ctx.fillStyle = 'rgba(0, 0, 0, 0.4)';
    ctx.beginPath();
    ctx.roundRect(x - width / 2 + 2, y - height / 2 + 2, width, height, 4);
    ctx.fill();

    // Badge background
    ctx.fillStyle = '#0F172A';
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.roundRect(x - width / 2, y - height / 2, width, height, 4);
    ctx.fill();
    ctx.stroke();

    // Badge text
    ctx.fillStyle = color;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(label, x, y);
}

