                        {/* Health Bar */}
                        <div>
                            <div className="flex items-center justify-between mb-1">
                                <span className="text-xs text-slate-500">Health</span>
                                <span className="text-xs font-medium" style={{ color: healthColor }}>
                                    {data.health}%
                                </span>
                            </div>
