'use client';

import { useSimulationStore } from '@/store/simulation-store';
import { useState, useCallback } from 'react';

export function LeftPanel() {
    const {
        currentLesson,
        currentStepIndex,
        setCurrentStep,
        setHighlight,
        clearHighlight,
        isPlaying,
        playbackSpeed,
        setPlaybackSpeed
    } = useSimulationStore();

    const currentStep = currentLesson?.steps[currentStepIndex];
    const [hoveredStep, setHoveredStep] = useState<number | null>(null);
    const [isSlowMotion, setIsSlowMotion] = useState(false);

    // Handle step hover - highlight involved nodes
    const handleStepHover = useCallback((stepIndex: number) => {
        setHoveredStep(stepIndex);
        const step = currentLesson?.steps[stepIndex];
        if (step) {
            // Highlight the first entity mentioned in this step
            const entityToHighlight = step.spawn?.[0]?.id ||
                step.updateEntities?.[0]?.id ||
                step.ui.highlight?.[0];
            if (entityToHighlight) {
                setHighlight(entityToHighlight);
            }
        }
    }, [currentLesson, setHighlight]);

    const handleStepLeave = useCallback(() => {
        setHoveredStep(null);
        clearHighlight();
    }, [clearHighlight]);

    // Allow replay of individual steps
    const handleStepClick = useCallback((stepIndex: number) => {
        if (stepIndex <= currentStepIndex) {
            setCurrentStep(stepIndex);
        }
    }, [currentStepIndex, setCurrentStep]);

    // Toggle slow motion mode
    const toggleSlowMotion = useCallback(() => {
        if (isSlowMotion) {
            setPlaybackSpeed(1);
            setIsSlowMotion(false);
        } else {
            setPlaybackSpeed(0.25);
            setIsSlowMotion(true);
        }
    }, [isSlowMotion, setPlaybackSpeed]);

    return (
        <aside
            className="w-64 flex flex-col border-r overflow-hidden"
            style={{
                background: 'linear-gradient(180deg, #0D1B2A 0%, #0A1628 100%)',
                borderColor: '#22D3EE30'
            }}
        >
            {/* Lesson System Header */}
            <div
                className="px-4 py-3 border-b"
                style={{ borderColor: '#22D3EE20' }}
            >
                <div className="flex items-center gap-2 mb-1">
                    <span className="text-cyan-400"></span>
                    <h2
                        className="text-xs font-bold uppercase tracking-wider"
                        style={{ color: '#22D3EE' }}
                    >
                        Lesson System
                    </h2>
                </div>
                {currentLesson && (
                    <div className="mt-2">
                        <p
                            className="text-[10px] uppercase tracking-wider mb-1"
                            style={{ color: '#64748B' }}
                        >
                            Current Lesson:
                        </p>
                        <p
                            className="text-sm font-semibold"
                            style={{ color: '#E2E8F0' }}
                        >
                            {currentLesson.title}
                        </p>
                    </div>
                )}
            </div>

            {/* Slow Motion Toggle */}
            {currentLesson && (
                <div className="px-4 py-2 border-b flex items-center justify-between"
                    style={{ borderColor: '#22D3EE20' }}>
                    <span className="text-[10px] uppercase tracking-wider" style={{ color: '#64748B' }}>
                        Teaching Mode
                    </span>
                    <button
                        onClick={toggleSlowMotion}
                        className={`px-2 py-1 rounded text-[10px] font-medium transition-all ${isSlowMotion ? 'ring-2 ring-purple-500' : ''
                            }`}
                        style={{
                            background: isSlowMotion ? '#8B5CF620' : '#1E293B',
                            color: isSlowMotion ? '#A78BFA' : '#64748B',
                            border: `1px solid ${isSlowMotion ? '#8B5CF6' : '#334155'}`
                        }}
                    >
                        ∩┐╜ {isSlowMotion ? 'Slow Motion ON' : 'Slow Motion'}
                    </button>
                </div>
            )}

            {/* Step List - Timeline */}
            {currentLesson && (
                <div
                    className="flex-1 overflow-y-auto p-2"
                    style={{ maxHeight: '220px' }}
                >
                    <div className="text-[9px] uppercase tracking-wider mb-2 px-2"
                        style={{ color: '#64748B' }}>
                        Timeline ({currentStepIndex + 1}/{currentLesson.steps.length})
                    </div>
                    {currentLesson.steps.map((step, index) => {
                        const isActive = index === currentStepIndex;
                        const isCompleted = index < currentStepIndex;
                        const isHovered = index === hoveredStep;
                        const canReplay = index <= currentStepIndex;

                        return (
                            <div
                                key={step.id}
                                className={`flex items-start gap-2 p-2 rounded-lg mb-1 transition-all cursor-pointer ${isActive ? 'bg-cyan-500/15' :
                                        isHovered && canReplay ? 'bg-slate-700/30' : ''
                                    }`}
                                style={{
                                    borderLeft: isActive
                                        ? '3px solid #22D3EE'
                                        : isHovered && canReplay
                                            ? '3px solid #64748B'
                                            : '3px solid transparent',
                                    opacity: isCompleted && !isActive ? 0.6 : 1,
                                    boxShadow: isActive ? '0 0 15px rgba(34, 211, 238, 0.15)' : 'none'
                                }}
                                onMouseEnter={() => handleStepHover(index)}
                                onMouseLeave={handleStepLeave}
                                onClick={() => handleStepClick(index)}
                            >
                                {/* Step indicator */}
                                <div
                                    className="w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold flex-shrink-0 mt-0.5 transition-all"
                                    style={{
                                        background: isCompleted
                                            ? '#22C55E'
                                            : isActive
                                                ? '#22D3EE'
                                                : '#1E293B',
                                        color: isCompleted || isActive ? '#0F172A' : '#64748B',
                                        border: `1px solid ${isCompleted ? '#22C55E' :
                                                isActive ? '#22D3EE' :
                                                    '#475569'
                                            }`,
                                        boxShadow: isActive ? '0 0 10px rgba(34, 211, 238, 0.5)' : 'none'
                                    }}
                                >
                                    {isCompleted ? 'Γ£ô' : index + 1}
                                </div>
                                <div className="flex-1 min-w-0">
                                    <p
                                        className="text-xs font-medium truncate"
                                        style={{
                                            color: isActive ? '#22D3EE' : isCompleted ? '#22C55E' : '#94A3B8'
                                        }}
                                    >
                                        {step.name}
                                    </p>
                                    <p
                                        className="text-[10px] truncate"
                                        style={{ color: '#64748B' }}
                                    >
                                        {step.ui.subtitle}
                                    </p>
                                </div>
                                {/* Replay indicator */}
                                {isCompleted && isHovered && (
                                    <span className="text-[9px]" style={{ color: '#64748B' }}>
                                        Γå⌐
                                    </span>
                                )}
                            </div>
                        );
                    })}
                </div>
            )}

            {/* AI Explanation */}
            <div
                className="flex-1 border-t overflow-y-auto"
                style={{ borderColor: '#22D3EE20' }}
            >
                <div className="px-4 py-3">
                    <div className="flex items-center gap-2 mb-3">
                        <span>∩┐╜</span>
                        <h3
                            className="text-xs font-bold uppercase tracking-wider"
                            style={{ color: '#8B5CF6' }}
                        >
                            AI Explanation
                        </h3>
                    </div>

                    {currentStep ? (
                        <div>
                            {/* Step Title */}
                            <h4
                                className="text-sm font-semibold mb-2"
                                style={{ color: '#E2E8F0' }}
                            >
                                {currentStep.ui.title}
                            </h4>

                            {/* Step Details */}
                            <ul className="space-y-1.5 mb-4">
                                {currentStep.ui.details?.map((detail, i) => (
                                    <li
                                        key={i}
                                        className="flex items-start gap-2 text-xs"
                                        style={{ color: '#94A3B8' }}
                                    >
                                        <span style={{ color: '#22D3EE' }}>ΓÇó</span>
                                        <span>{detail}</span>
                                    </li>
                                ))}
                            </ul>

                            {/* AI Insight */}
                            {currentStep.ui.aiExplanation && (
                                <div
                                    className="p-3 rounded-lg"
                                    style={{
                                        background: 'rgba(139, 92, 246, 0.1)',
                                        border: '1px solid rgba(139, 92, 246, 0.2)'
                                    }}
                                >
                                    <p className="text-xs font-medium mb-1" style={{ color: '#8B5CF6' }}>
                                         Did you know?
                                    </p>
                                    <p
                                        className="text-xs leading-relaxed"
                                        style={{ color: '#C4B5FD' }}
                                    >
                                        {currentStep.ui.aiExplanation}
                                    </p>
                                </div>
                            )}
                        </div>
                    ) : (
                        <div
                            className="text-center py-8"
                            style={{ color: '#64748B' }}
                        >
                            <p className="text-sm mb-2">No lesson loaded</p>
                            <p className="text-xs">Select a lesson to begin</p>
                        </div>
                    )}
                </div>
            </div>

            {/* Lesson Metadata */}
            {currentLesson && (
                <div
                    className="px-4 py-2 border-t flex items-center justify-between text-[10px]"
                    style={{
                        borderColor: '#22D3EE20',
                        color: '#64748B'
                    }}
                >
                    <span>{currentLesson.category}</span>
                    <span
                        className="px-1.5 py-0.5 rounded"
                        style={{
                            background: currentLesson.difficulty === 'beginner'
                                ? 'rgba(34, 197, 94, 0.2)'
                                : currentLesson.difficulty === 'intermediate'
                                    ? 'rgba(245, 158, 11, 0.2)'
                                    : 'rgba(239, 68, 68, 0.2)',
                            color: currentLesson.difficulty === 'beginner'
                                ? '#22C55E'
                                : currentLesson.difficulty === 'intermediate'
                                    ? '#F59E0B'
                                    : '#EF4444'
                        }}
                    >
                        {currentLesson.difficulty}
                    </span>
                </div>
            )}
        </aside>
    );
}

'use client';

// Neon Card component with animated border glow
// Glassmorphism style with hover effects

import { ReactNode, useRef, useEffect, useState, forwardRef } from 'react';
import anime from 'animejs';

interface NeonCardProps {
    children: ReactNode;
    variant?: 'default' | 'attack' | 'defense' | 'info' | 'warning';
    glow?: boolean;
    hover?: boolean;
    className?: string;
    onClick?: () => void;
}

const VARIANT_COLORS = {
    default: { border: '#22D3EE', bg: 'rgba(34, 211, 238, 0.05)' },
    attack: { border: '#EF4444', bg: 'rgba(239, 68, 68, 0.05)' },
    defense: { border: '#22C55E', bg: 'rgba(34, 197, 94, 0.05)' },
    info: { border: '#3B82F6', bg: 'rgba(59, 130, 246, 0.05)' },
    warning: { border: '#F59E0B', bg: 'rgba(245, 158, 11, 0.05)' },
};

export function NeonCard({
    children,
    variant = 'default',
    glow = true,
    hover = true,
    className = '',
    onClick,
}: NeonCardProps) {
    const cardRef = useRef<HTMLDivElement>(null);
    const [isHovered, setIsHovered] = useState(false);

    const colors = VARIANT_COLORS[variant];

    useEffect(() => {
        if (!hover || !cardRef.current) return;

        if (isHovered) {
            anime({
                targets: cardRef.current,
                boxShadow: `0 0 20px ${colors.border}40, 0 0 40px ${colors.border}20`,
                borderColor: colors.border,
                duration: 300,
                easing: 'easeOutExpo',
            });
        } else {
            anime({
                targets: cardRef.current,
                boxShadow: glow
                    ? `0 0 10px ${colors.border}20, 0 0 20px ${colors.border}10`
                    : '0 0 0px transparent',
                borderColor: `${colors.border}60`,
                duration: 300,
                easing: 'easeOutExpo',
            });
        }
    }, [isHovered, hover, glow, colors.border]);

    return (
        <div
            ref={cardRef}
            className={`relative rounded-lg backdrop-blur-sm transition-transform ${onClick ? 'cursor-pointer' : ''
                } ${hover ? 'hover:scale-[1.02] active:scale-[0.98]' : ''} ${className}`}
            style={{
                background: `linear-gradient(135deg, ${colors.bg} 0%, rgba(15, 23, 42, 0.8) 100%)`,
                border: `1px solid ${colors.border}60`,
                boxShadow: glow
                    ? `0 0 10px ${colors.border}20, 0 0 20px ${colors.border}10`
                    : 'none',
            }}
            onMouseEnter={() => setIsHovered(true)}
            onMouseLeave={() => setIsHovered(false)}
            onClick={onClick}
        >
            {children}
        </div>
    );
}

// Panel variant - larger, no hover effects
interface NeonPanelProps {
    children: ReactNode;
    title?: string;
    icon?: ReactNode;
    variant?: 'default' | 'attack' | 'defense' | 'info';
    className?: string;
}

export function NeonPanel({
    children,
    title,
    icon,
    variant = 'default',
    className = '',
}: NeonPanelProps) {
    const colors = VARIANT_COLORS[variant];

    return (
        <div
            className={`rounded-xl backdrop-blur-sm ${className}`}
            style={{
                background: `linear-gradient(180deg, ${colors.bg} 0%, rgba(15, 23, 42, 0.9) 100%)`,
                border: `1px solid ${colors.border}30`,
            }}
        >
            {title && (
                <div
                    className="flex items-center gap-2 px-4 py-3 border-b"
                    style={{ borderColor: `${colors.border}20` }}
                >
                    {icon}
                    <span
                        className="text-xs font-bold uppercase tracking-wider"
                        style={{ color: colors.border }}
                    >
                        {title}
                    </span>
                </div>
            )}
            <div className="p-4">
                {children}
            </div>
        </div>
    );
}

'use client';

import { useState } from 'react';
import { Quiz, QuizQuestion } from '@/types/lessons';
import { useSound } from '@/hooks/use-sound';

interface QuizModalProps {
    quiz: Quiz;
    isOpen: boolean;
    onClose: () => void;
    onComplete: (score: number) => void;
}

export function QuizModal({ quiz, isOpen, onClose, onComplete }: QuizModalProps) {
    const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
    const [selectedOption, setSelectedOption] = useState<number | null>(null);
    const [isAnswered, setIsAnswered] = useState(false);
    const [score, setScore] = useState(0);
    const [showResults, setShowResults] = useState(false);

    const { playSuccess, playError } = useSound();

    if (!isOpen) return null;

    const currentQuestion = quiz.questions[currentQuestionIndex];
    const totalQuestions = quiz.questions.length;

    const handleOptionSelect = (index: number) => {
        if (isAnswered) return;
        setSelectedOption(index);
        setIsAnswered(true);

        const isCorrect = index === currentQuestion.correctIndex;
        if (isCorrect) {
            setScore(prev => prev + 1);
            playSuccess();
        } else {
            playError();
        }
    };

    const handleNext = () => {
        if (currentQuestionIndex < totalQuestions - 1) {
            setCurrentQuestionIndex(prev => prev + 1);
            setSelectedOption(null);
            setIsAnswered(false);
        } else {
            setShowResults(true);
            onComplete(score + (selectedOption === currentQuestion.correctIndex ? 1 : 0));
        }
    };

    if (showResults) {
        const percentage = Math.round((score / totalQuestions) * 100);
        let message = '';
        let emoji = '';

        if (percentage >= 80) {
            message = 'Outstanding! You\'re a Cyber Master!';
            emoji = '∩┐╜';
        } else if (percentage >= 60) {
            message = 'Good job! Keep practicing.';
            emoji = '∩┐╜';
        } else {
            message = 'Review the lesson and try again.';
            emoji = '';
        }

        return (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm">
                <div
                    className="w-full max-w-md p-6 rounded-2xl border bg-slate-900 shadow-2xl transform transition-all"
                    style={{ borderColor: '#22D3EE40', boxShadow: '0 0 40px rgba(34, 211, 238, 0.1)' }}
                >
                    <div className="text-center mb-6">
                        <div className="text-6xl mb-4">{emoji}</div>
                        <h2 className="text-2xl font-bold text-white mb-2">Quiz Complete!</h2>
                        <p className="text-slate-400">{message}</p>
                    </div>

                    <div className="flex justify-center items-center gap-4 mb-8">
                        <div className="text-center p-4 rounded-xl bg-slate-800/50 border border-slate-700">
                            <div className="text-3xl font-bold text-cyan-400">{score}/{totalQuestions}</div>
                            <div className="text-xs text-slate-500 uppercase tracking-wider">Score</div>
                        </div>
                        <div className="text-center p-4 rounded-xl bg-slate-800/50 border border-slate-700">
                            <div className="text-3xl font-bold text-purple-400">{percentage}%</div>
                            <div className="text-xs text-slate-500 uppercase tracking-wider">Accuracy</div>
                        </div>
                    </div>

                    <button
                        onClick={onClose}
                        className="w-full py-3 rounded-xl font-bold text-white transition-all transform hover:scale-[1.02] active:scale-[0.98]"
                        style={{ background: 'linear-gradient(to right, #22D3EE, #3B82F6)' }}
                    >
                        Continue Journey
                    </button>
                </div>
            </div>
        );
    }

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm">
            <div
                className="w-full max-w-lg p-6 rounded-2xl border bg-slate-900 shadow-2xl"
                style={{ borderColor: '#22D3EE40' }}
            >
                {/* Header */}
                <div className="flex justify-between items-center mb-6">
                    <div>
                        <h2 className="text-xl font-bold text-white">{quiz.title}</h2>
                        <p className="text-xs text-slate-400">Question {currentQuestionIndex + 1} of {totalQuestions}</p>
                    </div>
                    <button onClick={onClose} className="text-slate-500 hover:text-white">Γ£ò</button>
                </div>

                {/* Question */}
                <div className="mb-6">
                    <p className="text-lg text-slate-200 font-medium leading-relaxed">
                        {currentQuestion.question}
                    </p>
                </div>

                {/* Options */}
                <div className="space-y-3 mb-6">
                    {currentQuestion.options.map((option, idx) => {
                        let optionStyle = 'bg-slate-800/50 border-slate-700 text-slate-300 hover:bg-slate-800';

                        if (isAnswered) {
                            if (idx === currentQuestion.correctIndex) {
                                optionStyle = 'bg-green-500/20 border-green-500 text-green-400';
                            } else if (idx === selectedOption) {
                                optionStyle = 'bg-red-500/20 border-red-500 text-red-400';
                            } else {
                                optionStyle = 'bg-slate-800/30 border-slate-800 text-slate-500 opacity-50';
                            }
                        } else if (selectedOption === idx) {
                            optionStyle = 'bg-cyan-500/20 border-cyan-500 text-cyan-400';
                        }

                        return (
                            <button
                                key={idx}
                                onClick={() => handleOptionSelect(idx)}
                                disabled={isAnswered}
                                className={`w-full p-4 rounded-xl text-left border transition-all ${optionStyle}`}
                            >
                                <div className="flex items-center gap-3">
                                    <div className={`w-6 h-6 rounded-full border flex items-center justify-center text-xs
                                        ${idx === currentQuestion.correctIndex && isAnswered ? 'bg-green-500 border-green-500 text-black' :
                                            idx === selectedOption && !isAnswered ? 'border-cyan-500 text-cyan-500' :
                                                idx === selectedOption && isAnswered ? 'border-red-500 text-red-500' :
                                                    'border-slate-600 text-slate-500'
                                        }
                                    `}>
                                        {String.fromCharCode(65 + idx)}
                                    </div>
                                    <span className="flex-1">{option}</span>
                                    {isAnswered && idx === currentQuestion.correctIndex && <span></span>}
                                    {isAnswered && idx === selectedOption && idx !== currentQuestion.correctIndex && <span></span>}
                                </div>
                            </button>
                        );
                    })}
                </div>

                {/* Explanation & Next Button */}
                {isAnswered && (
                    <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                        <div className="mb-6 p-4 rounded-lg bg-blue-500/10 border border-blue-500/30">
                            <h4 className="text-sm font-bold text-blue-400 mb-1">Explanation</h4>
                            <p className="text-sm text-slate-300">{currentQuestion.explanation}</p>
                        </div>

                        <button
                            onClick={handleNext}
                            className="w-full py-3 rounded-xl font-bold text-white transition-all transform hover:scale-[1.02] active:scale-[0.98]"
                            style={{ background: 'linear-gradient(to right, #22D3EE, #3B82F6)' }}
                        >
                            {currentQuestionIndex < totalQuestions - 1 ? 'Next Question' : 'See Results'}
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
}

'use client';

import { useSimulationStore } from '@/store/simulation-store';
import { useEffect, useRef } from 'react';
import Link from 'next/link';

const LOG_COLORS: Record<string, string> = {
    info: '#22D3EE',
    warning: '#F59E0B',
    error: '#EF4444',
    success: '#22C55E',
    attack: '#EF4444',
    defense: '#3B82F6'
};

const PROTOCOL_COLORS: Record<string, string> = {
    DHCP: '#FACC15',
    ARP: '#22D3EE',
    DNS: '#A855F7',
    TCP: '#3B82F6',
    HTTPS: '#22C55E',
    ATTACK: '#EF4444',
    SYN: '#EF4444'
};

interface RightPanelProps {
    onStartQuiz?: () => void;
}

export function RightPanel({ onStartQuiz }: RightPanelProps) {
    const {
        logs,
        clearLogs,
        entities,
        currentLesson,
        currentStepIndex,
    } = useSimulationStore();

    const logsEndRef = useRef<HTMLDivElement>(null);
    const isLessonActive = currentLesson !== null;
    const currentStep = currentLesson?.steps[currentStepIndex];
    const isLastStep = currentLesson && currentStepIndex === currentLesson.steps.length - 1;
    const hasQuiz = !!currentLesson?.quiz;

    useEffect(() => {
        logsEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [logs]);

    const formatTime = (timestamp: number) => {
        const date = new Date(timestamp);
        return date.toTimeString().substring(0, 8);
    };

    return (
        <aside
            className="w-72 flex flex-col border-l overflow-hidden"
            style={{
                background: 'linear-gradient(180deg, #0D1B2A 0%, #0A1628 100%)',
                borderColor: '#22D3EE30'
            }}
        >
            {/* No Lesson - Show Get Started */}
            {!isLessonActive ? (
                <div className="flex-1 flex flex-col p-4 overflow-y-auto">
                    <div className="text-center mb-6">
                        <div
                            className="w-14 h-14 rounded-2xl flex items-center justify-center mx-auto mb-3"
                            style={{
                                background: 'linear-gradient(135deg, #22D3EE 0%, #3B82F6 100%)',
                                boxShadow: '0 0 20px rgba(34, 211, 238, 0.3)'
                            }}
                        >
                            <span className="text-xl"></span>
                        </div>
                        <h3 className="text-base font-bold text-white mb-1">Get Started</h3>
                        <p className="text-xs text-slate-400">Select a lesson to begin</p>
                    </div>

                    <div className="space-y-2">
                        <Link
                            href="/lessons"
                            className="block p-3 rounded-xl transition-all hover:scale-[1.02]"
                            style={{ background: 'rgba(34, 211, 238, 0.1)', border: '1px solid rgba(34, 211, 238, 0.3)' }}
                        >
                            <div className="flex items-center gap-3">
                                <span className="text-xl"></span>
                                <div>
                                    <h4 className="text-sm font-semibold text-cyan-400">Browse Lessons</h4>
                                    <p className="text-[10px] text-slate-400">7 interactive lessons</p>
                                </div>
                            </div>
                        </Link>
                        <Link
                            href="/campaign"
                            className="block p-3 rounded-xl transition-all hover:scale-[1.02]"
                            style={{ background: 'rgba(139, 92, 246, 0.1)', border: '1px solid rgba(139, 92, 246, 0.3)' }}
                        >
                            <div className="flex items-center gap-3">
                                <span className="text-xl"></span>
                                <div>
                                    <h4 className="text-sm font-semibold text-purple-400">Campaign Mode</h4>
                                    <p className="text-[10px] text-slate-400">Progress through chapters</p>
                                </div>
                            </div>
                        </Link>
                    </div>
                </div>
            ) : (
                /* LESSON MODE */
                <div className="flex-1 flex flex-col overflow-hidden">
                    {/* What's Happening */}
                    <div className="p-3 border-b" style={{ borderColor: '#22D3EE20' }}>
                        <div className="flex items-center gap-2 mb-2">
                            <span></span>
                            <h3 className="text-xs font-bold uppercase tracking-wider text-cyan-400">
                                What's Happening
                            </h3>
                        </div>
                        {currentStep && (
                            <div>
                                <h4 className="text-sm font-semibold text-white mb-1">
                                    {currentStep.ui.title}
                                </h4>
                                <p className="text-[11px] text-slate-400 leading-relaxed">
                                    {currentStep.ui.subtitle}
                                </p>
                            </div>
                        )}
                        {isLastStep && hasQuiz && (
                            <button
                                onClick={onStartQuiz}
                                className="w-full mt-3 py-2 rounded-lg text-xs font-bold text-white transition-all hover:scale-[1.02] animate-pulse"
                                style={{
                                    background: 'linear-gradient(to right, #22D3EE, #3B82F6)',
                                    boxShadow: '0 0 15px rgba(34, 211, 238, 0.3)'
                                }}
                            >
                                ∩┐╜ Take Quiz
                            </button>
                        )}
                    </div>

                    {/* Device Status */}
                    <div className="p-3 border-b" style={{ borderColor: '#22D3EE20' }}>
                        <div className="flex items-center gap-2 mb-2">
                            <span></span>
                            <h3 className="text-xs font-bold uppercase tracking-wider text-purple-400">
                                Devices
                            </h3>
                        </div>
                        <div className="space-y-1.5">
                            {Array.from(entities.values()).slice(0, 5).map((entity) => (
                                <div
                                    key={entity.id}
                                    className="flex items-center gap-2 p-1.5 rounded"
                                    style={{ background: 'rgba(30, 41, 59, 0.5)' }}
                                >
                                    <div
                                        className="w-2 h-2 rounded-full flex-shrink-0"
                                        style={{
                                            backgroundColor: entity.status === 'active' ? '#22C55E' :
                                                entity.status === 'connecting' ? '#F59E0B' :
                                                    entity.status === 'compromised' ? '#EF4444' : '#64748B'
                                        }}
                                    />
                                    <span className="text-[11px] text-slate-200 truncate flex-1">
                                        {entity.metadata?.label || entity.type}
                                    </span>
                                    <span className="text-[9px] text-slate-500 capitalize">
                                        {entity.status || 'idle'}
                                    </span>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Network Activity */}
                    <div className="flex-1 flex flex-col overflow-hidden">
                        <div className="flex items-center justify-between px-3 py-2 border-b" style={{ borderColor: '#22D3EE20' }}>
                            <div className="flex items-center gap-2">
                                <span></span>
                                <h3 className="text-xs font-bold uppercase tracking-wider text-slate-400">
                                    Activity
                                </h3>
                                <span className="text-[9px] text-slate-500">{logs.length}</span>
                            </div>
                            <button
                                onClick={() => clearLogs()}
                                className="text-[9px] px-1.5 py-0.5 rounded hover:bg-slate-700"
                                style={{ background: '#1E293B', color: '#64748B' }}
                            >
                                Clear
                            </button>
                        </div>

                        <div className="flex-1 overflow-y-auto p-2 space-y-1">
                            {logs.length === 0 ? (
                                <div className="text-center py-4 text-[10px] text-slate-500">
                                    Waiting for activity...
                                </div>
                            ) : (
                                logs.slice(-15).map((log) => (
                                    <div
                                        key={log.id}
                                        className="flex items-start gap-1 p-1 rounded"
                                        style={{
                                            background: '#0F172A80',
                                            borderLeft: `2px solid ${LOG_COLORS[log.type] || '#64748B'}`
                                        }}
                                    >
                                        <span className="text-[8px] text-slate-500 font-mono flex-shrink-0">
                                            {formatTime(log.timestamp).slice(3, 8)}
                                        </span>
                                        <span className="text-[10px] text-slate-300 flex-1">{log.message}</span>
                                        {log.protocol && (
                                            <span
                                                className="px-1 rounded text-[7px] font-bold flex-shrink-0"
                                                style={{ background: PROTOCOL_COLORS[log.protocol] || '#64748B', color: '#0F172A' }}
                                            >
                                                {log.protocol}
                                            </span>
                                        )}
                                    </div>
                                ))
                            )}
                            <div ref={logsEndRef} />
                        </div>
                    </div>
                </div>
            )}
        </aside>
    );
}

