'use client';

// Base Tooltip Component
// Floating tooltip with smart positioning and animations

import { ReactNode, useEffect, useRef, useState, useCallback } from 'react';
import { createPortal } from 'react-dom';
import anime from 'animejs';

interface TooltipProps {
    children: ReactNode;
    visible: boolean;
    x: number;
    y: number;
    offset?: { x: number; y: number };
    delay?: number;
    className?: string;
}

export function Tooltip({
    children,
    visible,
    x,
    y,
    offset = { x: 12, y: 12 },
    delay = 0,
    className = '',
}: TooltipProps) {
    const tooltipRef = useRef<HTMLDivElement>(null);
    const [mounted, setMounted] = useState(false);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const [shouldRender, setShouldRender] = useState(false);
    const showTimeoutRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
    const hideTimeoutRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

    // Handle mounting for portal
    useEffect(() => {
        setMounted(true);
        return () => setMounted(false);
    }, []);

    // Calculate position avoiding screen edges
    const calculatePosition = useCallback(() => {
        if (!tooltipRef.current) return { x: 0, y: 0 };

        const tooltip = tooltipRef.current;
        const rect = tooltip.getBoundingClientRect();
        const padding = 16;

        let posX = x + offset.x;
        let posY = y + offset.y;

        // Flip horizontally if too close to right edge
        if (posX + rect.width > window.innerWidth - padding) {
            posX = x - rect.width - offset.x;
        }

        // Flip vertically if too close to bottom edge
        if (posY + rect.height > window.innerHeight - padding) {
            posY = y - rect.height - offset.y;
        }

        // Keep within left bound
        if (posX < padding) {
            posX = padding;
        }

        // Keep within top bound
        if (posY < padding) {
            posY = padding;
        }

        return { x: posX, y: posY };
    }, [x, y, offset]);

    // Handle visibility with delay
    useEffect(() => {
        if (visible) {
            clearTimeout(hideTimeoutRef.current);

            if (delay > 0) {
                showTimeoutRef.current = setTimeout(() => {
                    setShouldRender(true);
                }, delay);
            } else {
                setShouldRender(true);
            }
        } else {
            clearTimeout(showTimeoutRef.current);

            // Short delay before hiding for smoother experience
            hideTimeoutRef.current = setTimeout(() => {
                setShouldRender(false);
            }, 100);
        }

        return () => {
            clearTimeout(showTimeoutRef.current);
            clearTimeout(hideTimeoutRef.current);
        };
    }, [visible, delay]);

    // Update position when visible and recalculate
    useEffect(() => {
        if (shouldRender) {
            // Wait for render then calculate position
            requestAnimationFrame(() => {
                setPosition(calculatePosition());
            });
        }
    }, [shouldRender, calculatePosition, x, y]);

    // Animate in/out
    useEffect(() => {
        if (!tooltipRef.current) return;

        if (shouldRender) {
            anime({
                targets: tooltipRef.current,
                opacity: [0, 1],
                scale: [0.95, 1],
                translateY: [5, 0],
                duration: 200,
                easing: 'easeOutExpo',
            });
        }
    }, [shouldRender]);

    // Debug logging - remove after fix
    console.log('[Tooltip Debug]', { visible, shouldRender, mounted, x, y });

    if (!mounted || !shouldRender) return null;

    return createPortal(
        <div
            ref={tooltipRef}
            className={`fixed z-[9999] pointer-events-none ${className}`}
            style={{
                left: position.x,
                top: position.y,
                opacity: 0,
            }}
        >
            {children}
        </div>,
        document.body
    );
}

// Tooltip content wrapper with cyber styling
interface TooltipContentProps {
    children: ReactNode;
    variant?: 'default' | 'info' | 'warning' | 'error' | 'success';
    className?: string;
}

const VARIANT_STYLES = {
    default: {
        border: 'rgba(34, 211, 238, 0.3)',
        glow: 'rgba(34, 211, 238, 0.2)',
    },
    info: {
        border: 'rgba(59, 130, 246, 0.3)',
        glow: 'rgba(59, 130, 246, 0.2)',
    },
    warning: {
        border: 'rgba(245, 158, 11, 0.3)',
        glow: 'rgba(245, 158, 11, 0.2)',
    },
    error: {
        border: 'rgba(239, 68, 68, 0.3)',
        glow: 'rgba(239, 68, 68, 0.2)',
    },
    success: {
        border: 'rgba(34, 197, 94, 0.3)',
        glow: 'rgba(34, 197, 94, 0.2)',
    },
};

export function TooltipContent({
    children,
    variant = 'default',
    className = '',
}: TooltipContentProps) {
    const styles = VARIANT_STYLES[variant];

    return (
        <div
            className={`rounded-lg backdrop-blur-md p-3 ${className}`}
            style={{
                background: 'rgba(15, 23, 42, 0.95)',
                border: `1px solid ${styles.border}`,
                boxShadow: `0 4px 20px rgba(0, 0, 0, 0.5), 0 0 20px ${styles.glow}`,
                maxWidth: '320px',
            }}
        >
            {children}
        </div>
    );
}

// Hook for managing tooltip state
export function useTooltip(delay = 300) {
    const [state, setState] = useState({
        visible: false,
        x: 0,
        y: 0,
        data: null as unknown,
    });

    const show = useCallback((x: number, y: number, data?: unknown) => {
        setState({ visible: true, x, y, data: data ?? null });
    }, []);

    const hide = useCallback(() => {
        setState(prev => ({ ...prev, visible: false }));
    }, []);

    const updatePosition = useCallback((x: number, y: number) => {
        setState(prev => ({ ...prev, x, y }));
    }, []);

    return {
        ...state,
        show,
        hide,
        updatePosition,
        delay,
    };
}

// Attack Engine - Manages attack state machines
// Pure functions that process attacks and generate malicious packets

import {
    WorldState,
    ActiveAttack,
    AttackType,
    AttackPhase,
    Packet,
    Node,
    EventLog
} from './world-state';

function generateId(prefix: string, seed: number, counter: number): string {
    return `${prefix}-${seed}-${counter}`;
}

// ===== ATTACK FACTORIES =====
export function createAttack(
    id: string,
    type: AttackType,
    originNode: string,
    targetNode: string,
    intensity: number,
    startTick: number
): ActiveAttack {
    const durations: Record<AttackType, number> = {
        ddos: 100,
        sql_injection: 30,
        malware: 50,
        mitm: 80,
        phishing: 40,
        ransomware: 60
    };

    return {
        id,
        type,
        originNode,
        targetNode,
        intensity: Math.min(10, Math.max(1, intensity)),
        progress: 0,
        phase: 'preparing',
        packetsSpawned: 0,
        startedAt: startTick,
        duration: durations[type]
    };
}

// ===== DDOS ATTACK =====
function processDDoSAttack(world: WorldState, attack: ActiveAttack): WorldState {
    const targetNode = world.nodes.get(attack.targetNode);
    if (!targetNode) return world;

    const ticksElapsed = world.time - attack.startedAt;
    const newPackets: Packet[] = [...world.packets];
    const logs: EventLog[] = [...world.logs];
    let updatedAttack = { ...attack };

    // Phase transitions
    if (ticksElapsed < 5) {
        updatedAttack.phase = 'preparing';
    } else if (ticksElapsed < 10) {
        updatedAttack.phase = 'launching';
    } else if (ticksElapsed < attack.duration - 10) {
        updatedAttack.phase = 'active';
    } else if (ticksElapsed < attack.duration) {
        updatedAttack.phase = 'subsiding';
    } else {
        updatedAttack.phase = 'complete';
    }

    // Spawn attack packets during active phase
    if (updatedAttack.phase === 'active' || updatedAttack.phase === 'launching') {
        const packetsToSpawn = attack.intensity * 2;

        for (let i = 0; i < packetsToSpawn; i++) {
            const attackPacket: Packet = {
                id: generateId('ddos', world.seed, world.time * 100 + i),
                protocol: 'ATTACK_DDOS',
                source: attack.originNode,
                destination: attack.targetNode,
                path: [attack.originNode, attack.targetNode],
                currentHopIndex: 0,
                payload: { type: 'flood', size: 1500 },
                malicious: true,
                encrypted: false,
                createdAt: world.time,
                ttl: 5
            };
            newPackets.push(attackPacket);
            updatedAttack.packetsSpawned++;
        }

        // Log attack activity
        if (ticksElapsed % 10 === 0) {
            logs.push({
                id: generateId('log', world.seed, world.time),
                time: world.time,
                type: 'attack',
                message: `DDoS: ${packetsToSpawn} packets flooding ${targetNode.label}`,
                nodeIds: [attack.originNode, attack.targetNode]
            });
        }
    }

    // Update progress
    updatedAttack.progress = Math.min(100, (ticksElapsed / attack.duration) * 100);

    // Update target node health based on attack
    let updatedNode = targetNode;
    if (updatedAttack.phase === 'active') {
        const damage = attack.intensity * 0.5;
        updatedNode = {
            ...targetNode,
            health: Math.max(0, targetNode.health - damage),
            status: targetNode.health < 30 ? 'overloaded' : targetNode.status,
            packetsReceivedThisTick: targetNode.packetsReceivedThisTick + attack.intensity * 2
        };
    }

    const newNodes = new Map(world.nodes);
    newNodes.set(attack.targetNode, updatedNode);

    const newAttacks = world.attacks.map(a =>
        a.id === attack.id ? updatedAttack : a
    );

    return {
        ...world,
        nodes: newNodes,
        packets: newPackets,
        attacks: newAttacks,
        logs
    };
}

// ===== SQL INJECTION ATTACK =====
function processSQLInjectionAttack(world: WorldState, attack: ActiveAttack): WorldState {
    const targetNode = world.nodes.get(attack.targetNode);
    if (!targetNode) return world;

    const ticksElapsed = world.time - attack.startedAt;
    const logs: EventLog[] = [...world.logs];
    let updatedAttack = { ...attack };

    // Phase transitions
    if (ticksElapsed < 3) {
        updatedAttack.phase = 'preparing';
    } else if (ticksElapsed < 8) {
        updatedAttack.phase = 'launching';

        // Send SQL injection packet
        if (ticksElapsed === 5) {
            const sqlPacket: Packet = {
                id: generateId('sql', world.seed, world.time),
                protocol: 'ATTACK_SQL',
                source: attack.originNode,
                destination: attack.targetNode,
                path: [attack.originNode, attack.targetNode],
                currentHopIndex: 0,
                payload: {
                    query: "'; DROP TABLE users; --",
                    type: 'injection'
                },
                malicious: true,
                encrypted: false,
                createdAt: world.time,
                ttl: 10
            };

            // Check if WAF blocks it
            if (targetNode.security.wafEnabled) {
                updatedAttack.phase = 'blocked';
                logs.push({
                    id: generateId('log', world.seed, world.time),
                    time: world.time,
                    type: 'defense',
                    message: `WAF: Blocked SQL injection attempt on ${targetNode.label}`,
                    nodeIds: [attack.targetNode]
                });
            } else {
                return {
                    ...world,
                    packets: [...world.packets, sqlPacket],
                    attacks: world.attacks.map(a => a.id === attack.id ? updatedAttack : a),
                    logs
                };
            }
        }
    } else if (ticksElapsed < attack.duration) {
        if (updatedAttack.phase !== 'blocked') {
            updatedAttack.phase = 'active';
        }
    } else {
        updatedAttack.phase = 'complete';
    }

    // If attack succeeded, compromise the node
    let updatedNode = targetNode;
    if (updatedAttack.phase === 'active' && !targetNode.security.wafEnabled) {
        updatedNode = {
            ...targetNode,
            status: 'compromised',
            health: Math.max(0, targetNode.health - 20)
        };

        if (ticksElapsed === 10) {
            logs.push({
                id: generateId('log', world.seed, world.time),
                time: world.time,
                type: 'attack',
                message: `SQL Injection: ${targetNode.label} database compromised!`,
                nodeIds: [attack.targetNode]
            });
        }
    }

    updatedAttack.progress = Math.min(100, (ticksElapsed / attack.duration) * 100);

    const newNodes = new Map(world.nodes);
    newNodes.set(attack.targetNode, updatedNode);

    return {
        ...world,
        nodes: newNodes,
        attacks: world.attacks.map(a => a.id === attack.id ? updatedAttack : a),
        logs
    };
}

// ===== MALWARE ATTACK =====
function processMalwareAttack(world: WorldState, attack: ActiveAttack): WorldState {
    const targetNode = world.nodes.get(attack.targetNode);
    if (!targetNode) return world;

    const ticksElapsed = world.time - attack.startedAt;
    const logs: EventLog[] = [...world.logs];
    let updatedAttack = { ...attack };

    if (ticksElapsed < 5) {
        updatedAttack.phase = 'preparing';
    } else if (ticksElapsed < 15) {
        updatedAttack.phase = 'launching';

        // Send malware packet
        if (ticksElapsed === 8) {
            const malwarePacket: Packet = {
                id: generateId('malware', world.seed, world.time),
                protocol: 'ATTACK_MALWARE',
                source: attack.originNode,
                destination: attack.targetNode,
                path: [attack.originNode, attack.targetNode],
                currentHopIndex: 0,
                payload: { type: 'trojan', signature: 'XYZ123' },
                malicious: true,
                encrypted: true, // Often encrypted to evade detection
                createdAt: world.time,
                ttl: 10
            };

            // Check antivirus
            if (targetNode.security.antivirus) {
                updatedAttack.phase = 'blocked';
                logs.push({
                    id: generateId('log', world.seed, world.time),
                    time: world.time,
                    type: 'defense',
                    message: `Antivirus: Blocked malware on ${targetNode.label}`,
                    nodeIds: [attack.targetNode]
                });
            } else {
                return {
                    ...world,
                    packets: [...world.packets, malwarePacket],
                    attacks: world.attacks.map(a => a.id === attack.id ? updatedAttack : a),
                    logs
                };
            }
        }
    } else if (ticksElapsed < attack.duration) {
        if (updatedAttack.phase !== 'blocked') {
            updatedAttack.phase = 'active';
        }
    } else {
        updatedAttack.phase = 'complete';
    }

    // If infected, node starts spawning packets silently
    let updatedNode = targetNode;
    const newPackets = [...world.packets];

    if (updatedAttack.phase === 'active' && !targetNode.security.antivirus) {
        updatedNode = {
            ...targetNode,
            status: 'infected'
        };

        // Infected node spawns C2 packets every 10 ticks
        if (ticksElapsed % 10 === 0 && ticksElapsed > 15) {
            const c2Packet: Packet = {
                id: generateId('c2', world.seed, world.time),
                protocol: 'TCP_DATA',
                source: attack.targetNode,
                destination: attack.originNode,
                path: [attack.targetNode, attack.originNode],
                currentHopIndex: 0,
                payload: { type: 'exfiltration' },
                malicious: true,
                encrypted: true,
                createdAt: world.time,
                ttl: 5
            };
            newPackets.push(c2Packet);
        }
    }

    updatedAttack.progress = Math.min(100, (ticksElapsed / attack.duration) * 100);

    const newNodes = new Map(world.nodes);
    newNodes.set(attack.targetNode, updatedNode);

    return {
        ...world,
        nodes: newNodes,
        packets: newPackets,
        attacks: world.attacks.map(a => a.id === attack.id ? updatedAttack : a),
        logs
    };
}

// ===== MITM ATTACK =====
function processMITMAttack(world: WorldState, attack: ActiveAttack): WorldState {
    const ticksElapsed = world.time - attack.startedAt;
    const logs: EventLog[] = [...world.logs];
    let updatedAttack = { ...attack };

    if (ticksElapsed < 10) {
        updatedAttack.phase = 'preparing';

        if (ticksElapsed === 5) {
            logs.push({
                id: generateId('log', world.seed, world.time),
                time: world.time,
                type: 'attack',
                message: `MITM: Attacker poisoning ARP tables...`,
                nodeIds: [attack.originNode]
            });
        }
    } else if (ticksElapsed < attack.duration - 10) {
        updatedAttack.phase = 'active';

        // Intercept packets
        if (ticksElapsed % 15 === 0) {
            logs.push({
                id: generateId('log', world.seed, world.time),
                time: world.time,
                type: 'attack',
                message: `MITM: Intercepting traffic between nodes`,
                nodeIds: [attack.originNode, attack.targetNode]
            });
        }
    } else if (ticksElapsed < attack.duration) {
        updatedAttack.phase = 'subsiding';
    } else {
        updatedAttack.phase = 'complete';
    }

    updatedAttack.progress = Math.min(100, (ticksElapsed / attack.duration) * 100);

    return {
        ...world,
        attacks: world.attacks.map(a => a.id === attack.id ? updatedAttack : a),
        logs
    };
}

// ===== ATTACK PROCESSOR =====
export function processAttacks(world: WorldState): WorldState {
    let newWorld = world;

    for (const attack of world.attacks) {
        if (attack.phase === 'complete' || attack.phase === 'blocked') {
            continue;
        }

        switch (attack.type) {
            case 'ddos':
                newWorld = processDDoSAttack(newWorld, attack);
                break;
            case 'sql_injection':
                newWorld = processSQLInjectionAttack(newWorld, attack);
                break;
            case 'malware':
                newWorld = processMalwareAttack(newWorld, attack);
                break;
            case 'mitm':
                newWorld = processMITMAttack(newWorld, attack);
                break;
            default:
                // Handle other attack types similarly
                break;
        }
    }

    // Remove completed attacks after some time
    const cleanedAttacks = newWorld.attacks.filter(attack => {
        if (attack.phase === 'complete' || attack.phase === 'blocked') {
            return world.time - attack.startedAt < attack.duration + 20;
        }
        return true;
    });

    return {
        ...newWorld,
        attacks: cleanedAttacks
    };
}

// ===== START ATTACK =====
export function startAttack(
    world: WorldState,
    type: AttackType,
    originNode: string,
    targetNode: string,
    intensity: number = 5
): WorldState {
    const attack = createAttack(
        generateId('attack', world.seed, world.time),
        type,
        originNode,
        targetNode,
        intensity,
        world.time
    );

    const log: EventLog = {
        id: generateId('log', world.seed, world.time),
        time: world.time,
        type: 'attack',
        message: `Attack started: ${type.toUpperCase()} targeting ${targetNode}`,
        nodeIds: [originNode, targetNode]
    };

    return {
        ...world,
        attacks: [...world.attacks, attack],
        logs: [...world.logs, log],
        phase: 'under_attack'
    };
}

// Defense Engine - Manages defense mechanisms
// Pure functions that process defenses and mitigate attacks

import {
    WorldState,
    ActiveDefense,
    DefenseType,
    Node,
    Packet,
    EventLog
} from './world-state';

function generateId(prefix: string, seed: number, counter: number): string {
    return `${prefix}-${seed}-${counter}`;
}

// ===== DEFENSE FACTORIES =====
export function createDefense(
    id: string,
    type: DefenseType,
    targetNode: string,
    config: Record<string, unknown>,
    startTick: number,
    duration: number = -1 // -1 = permanent
): ActiveDefense {
    const effectiveness: Record<DefenseType, number> = {
        firewall: 80,
        waf: 90,
        rate_limit: 70,
        block_ip: 95,
        dns_filter: 75,
        quarantine: 100,
        backup_restore: 100
    };

    return {
        id,
        type,
        targetNode,
        config,
        activatedAt: startTick,
        duration,
        effectiveness: effectiveness[type]
    };
}

// ===== FIREWALL DEFENSE =====
export function applyFirewall(world: WorldState, defense: ActiveDefense): WorldState {
    const targetNode = world.nodes.get(defense.targetNode);
    if (!targetNode) return world;

    // Update node security config
    const updatedNode: Node = {
        ...targetNode,
        security: {
            ...targetNode.security,
            firewallEnabled: true
        }
    };

    const newNodes = new Map(world.nodes);
    newNodes.set(defense.targetNode, updatedNode);

    // Filter out malicious packets targeting this node
    const blockedCount = world.packets.filter(
        p => p.destination === defense.targetNode && p.malicious
    ).length;

    const filteredPackets = world.packets.filter(
        p => !(p.destination === defense.targetNode && p.malicious && !p.encrypted)
    );

    const logs = [...world.logs];
    if (blockedCount > 0) {
        logs.push({
            id: generateId('log', world.seed, world.time),
            time: world.time,
            type: 'defense',
            message: `Firewall: Blocked ${blockedCount} malicious packets`,
            nodeIds: [defense.targetNode]
        });
    }

    return {
        ...world,
        nodes: newNodes,
        packets: filteredPackets,
        logs
    };
}

// ===== WAF (Web Application Firewall) =====
export function applyWAF(world: WorldState, defense: ActiveDefense): WorldState {
    const targetNode = world.nodes.get(defense.targetNode);
    if (!targetNode) return world;

    const updatedNode: Node = {
        ...targetNode,
        security: {
            ...targetNode.security,
            wafEnabled: true
        }
    };

    const newNodes = new Map(world.nodes);
    newNodes.set(defense.targetNode, updatedNode);

    // Block SQL injection and similar application-layer attacks
    const blockedPackets = world.packets.filter(
        p => p.destination === defense.targetNode &&
            (p.protocol === 'ATTACK_SQL' ||
                (p.payload.type === 'injection'))
    );

    const filteredPackets = world.packets.filter(
        p => !(p.destination === defense.targetNode &&
            (p.protocol === 'ATTACK_SQL' ||
                (p.payload.type === 'injection')))
    );

    const logs = [...world.logs];
    if (blockedPackets.length > 0) {
        logs.push({
            id: generateId('log', world.seed, world.time),
            time: world.time,
            type: 'defense',
            message: `WAF: Blocked ${blockedPackets.length} injection attempts`,
            nodeIds: [defense.targetNode]
        });
    }

    return {
        ...world,
        nodes: newNodes,
        packets: filteredPackets,
        logs
    };
}

// ===== RATE LIMITING =====
export function applyRateLimit(world: WorldState, defense: ActiveDefense): WorldState {
    const targetNode = world.nodes.get(defense.targetNode);
    if (!targetNode) return world;

    const rateLimit = (defense.config.limit as number) || 10;

    // Count packets to this node
    const packetsToNode = world.packets.filter(p => p.destination === defense.targetNode);

    const logs = [...world.logs];
    let filteredPackets = world.packets;

    if (packetsToNode.length > rateLimit) {
        // Drop excess packets, prioritizing malicious ones
        const maliciousPackets = packetsToNode.filter(p => p.malicious);
        const legitimatePackets = packetsToNode.filter(p => !p.malicious);

        const packetsToKeep = [
            ...legitimatePackets.slice(0, rateLimit),
            ...maliciousPackets.slice(0, Math.max(0, rateLimit - legitimatePackets.length))
        ];

        const packetIdsToKeep = new Set(packetsToKeep.map(p => p.id));
        const droppedCount = packetsToNode.length - packetsToKeep.length;

        filteredPackets = world.packets.filter(
            p => p.destination !== defense.targetNode || packetIdsToKeep.has(p.id)
        );

        if (droppedCount > 0) {
            logs.push({
                id: generateId('log', world.seed, world.time),
                time: world.time,
                type: 'defense',
                message: `Rate Limit: Dropped ${droppedCount} excess packets`,
                nodeIds: [defense.targetNode]
            });
        }
    }

    const updatedNode: Node = {
        ...targetNode,
        security: {
            ...targetNode.security,
            rateLimit
        }
    };

    const newNodes = new Map(world.nodes);
    newNodes.set(defense.targetNode, updatedNode);

    return {
        ...world,
        nodes: newNodes,
        packets: filteredPackets,
        logs
    };
}

// ===== IP BLOCKING =====
export function applyIPBlock(world: WorldState, defense: ActiveDefense): WorldState {
    const targetNode = world.nodes.get(defense.targetNode);
    if (!targetNode) return world;

    const blockedIP = defense.config.ip as string;
    const blockedNodeId = defense.config.nodeId as string;

    // Find node by IP or ID
    let sourceToBlock: string | undefined;
    if (blockedNodeId) {
        sourceToBlock = blockedNodeId;
    } else if (blockedIP) {
        for (const [id, node] of world.nodes) {
            if (node.ip === blockedIP) {
                sourceToBlock = id;
                break;
            }
        }
    }

    if (!sourceToBlock) return world;

    // Block all packets from this source
    const blockedCount = world.packets.filter(
        p => p.source === sourceToBlock && p.destination === defense.targetNode
    ).length;

    const filteredPackets = world.packets.filter(
        p => !(p.source === sourceToBlock && p.destination === defense.targetNode)
    );

    const logs = [...world.logs];
    if (blockedCount > 0) {
        logs.push({
            id: generateId('log', world.seed, world.time),
            time: world.time,
            type: 'defense',
            message: `IP Block: Blocked ${blockedCount} packets from ${blockedIP || sourceToBlock}`,
            nodeIds: [defense.targetNode, sourceToBlock]
        });
    }

    // Update blocked IPs list
    const updatedNode: Node = {
        ...targetNode,
        security: {
            ...targetNode.security,
            blockedIPs: [...targetNode.security.blockedIPs, blockedIP || sourceToBlock]
        }
    };

    const newNodes = new Map(world.nodes);
    newNodes.set(defense.targetNode, updatedNode);

    return {
        ...world,
        nodes: newNodes,
        packets: filteredPackets,
        logs
    };
}

// ===== QUARANTINE =====
export function applyQuarantine(world: WorldState, defense: ActiveDefense): WorldState {
    const targetNode = world.nodes.get(defense.targetNode);
    if (!targetNode) return world;

    // Disconnect node from network
    const updatedNode: Node = {
        ...targetNode,
        status: 'quarantined',
        connections: []
    };

    const newNodes = new Map(world.nodes);
    newNodes.set(defense.targetNode, updatedNode);

    // Block all links to/from this node
    const newLinks = new Map(world.links);
    for (const [id, link] of newLinks) {
        if (link.from === defense.targetNode || link.to === defense.targetNode) {
            newLinks.set(id, { ...link, blocked: true });
        }
    }

    // Remove all packets to/from this node
    const filteredPackets = world.packets.filter(
        p => p.source !== defense.targetNode && p.destination !== defense.targetNode
    );

    const logs: EventLog[] = [...world.logs, {
        id: generateId('log', world.seed, world.time),
        time: world.time,
        type: 'defense',
        message: `Quarantine: ${targetNode.label} isolated from network`,
        nodeIds: [defense.targetNode]
    }];

    return {
        ...world,
        nodes: newNodes,
        links: newLinks,
        packets: filteredPackets,
        logs
    };
}

// ===== BACKUP RESTORE =====
export function applyBackupRestore(world: WorldState, defense: ActiveDefense): WorldState {
    const targetNode = world.nodes.get(defense.targetNode);
    if (!targetNode) return world;

    // Restore node to healthy state
    const updatedNode: Node = {
        ...targetNode,
        status: 'idle',
        health: 100,
        security: {
            ...targetNode.security,
            // Keep security settings but clear infection
        }
    };

    const newNodes = new Map(world.nodes);
    newNodes.set(defense.targetNode, updatedNode);

    const logs: EventLog[] = [...world.logs, {
        id: generateId('log', world.seed, world.time),
        time: world.time,
        type: 'defense',
        message: `Backup Restore: ${targetNode.label} restored to healthy state`,
        nodeIds: [defense.targetNode]
    }];

    return {
        ...world,
        nodes: newNodes,
        logs
    };
}

// ===== DEFENSE PROCESSOR =====
export function processDefenses(world: WorldState): WorldState {
    let newWorld = world;

    for (const defense of world.defenses) {
        // Check if defense has expired
        if (defense.duration > 0) {
            const elapsed = world.time - defense.activatedAt;
            if (elapsed > defense.duration) {
                continue; // Skip expired defenses
            }
        }

        switch (defense.type) {
            case 'firewall':
                newWorld = applyFirewall(newWorld, defense);
                break;
            case 'waf':
                newWorld = applyWAF(newWorld, defense);
                break;
            case 'rate_limit':
                newWorld = applyRateLimit(newWorld, defense);
                break;
            case 'block_ip':
                newWorld = applyIPBlock(newWorld, defense);
                break;
            case 'quarantine':
                newWorld = applyQuarantine(newWorld, defense);
                break;
            case 'backup_restore':
                newWorld = applyBackupRestore(newWorld, defense);
                break;
            default:
                break;
        }
    }

    // Remove expired defenses
    const activeDefenses = newWorld.defenses.filter(defense => {
        if (defense.duration === -1) return true; // Permanent
        return world.time - defense.activatedAt < defense.duration;
    });

    // Check if we're defending
    const hasActiveDefenses = activeDefenses.length > 0;
    const hasActiveAttacks = newWorld.attacks.some(a => a.phase === 'active');

    let phase = newWorld.phase;
    if (hasActiveAttacks && hasActiveDefenses) {
        phase = 'defending';
    } else if (!hasActiveAttacks && newWorld.phase === 'defending') {
        phase = 'secured';
    }

    return {
        ...newWorld,
        defenses: activeDefenses,
        phase
    };
}

// ===== ACTIVATE DEFENSE =====
export function activateDefense(
    world: WorldState,
    type: DefenseType,
    targetNode: string,
    config: Record<string, unknown> = {},
    duration: number = -1
): WorldState {
    const defense = createDefense(
        generateId('defense', world.seed, world.time),
        type,
        targetNode,
        config,
        world.time,
        duration
    );

    const log: EventLog = {
        id: generateId('log', world.seed, world.time),
        time: world.time,
        type: 'defense',
        message: `Defense activated: ${type.replace('_', ' ').toUpperCase()} on ${targetNode}`,
        nodeIds: [targetNode]
    };

    return {
        ...world,
        defenses: [...world.defenses, defense],
        logs: [...world.logs, log]
    };
}

// Lesson Runtime Engine - Drives lesson progression based on world state
// Pure functions that evaluate conditions and trigger actions

import {
    WorldState,
    LessonStep,
    LessonCondition,
    LessonAction,
    LessonRuntimeState,
    EventLog,
    createDefaultNode,
    createDefaultLink,
    NodeType,
    PacketProtocol,
    Packet,
    AttackType,
    DefenseType
} from './world-state';
import { startAttack } from './attack-engine';
import { activateDefense } from './defense-engine';

function generateId(prefix: string, seed: number, counter: number): string {
    return `${prefix}-${seed}-${counter}`;
}

// ===== CONDITION EVALUATION =====
export function evaluateCondition(world: WorldState, condition: LessonCondition): boolean {
    switch (condition.type) {
        case 'node_status': {
            if (!condition.nodeId || !condition.status) return false;
            const node = world.nodes.get(condition.nodeId);
            return node?.status === condition.status;
        }

        case 'packet_arrived': {
            if (!condition.nodeId || !condition.protocol) return false;
            // Check logs for packet arrival
            return world.logs.some(log =>
                log.type === 'protocol' &&
                log.nodeIds.includes(condition.nodeId!) &&
                log.message.includes(condition.protocol!)
            );
        }

        case 'attack_started': {
            return world.attacks.some(a =>
                a.phase === 'active' || a.phase === 'launching'
            );
        }

        case 'defense_active': {
            if (!condition.nodeId) return world.defenses.length > 0;
            return world.defenses.some(d => d.targetNode === condition.nodeId);
        }

        case 'health_below': {
            const threshold = condition.threshold ?? 50;
            return world.metrics.networkHealth < threshold;
        }

        case 'time_elapsed': {
            const lesson = world.lesson;
            if (!lesson || !condition.ticks) return false;
            return world.time - lesson.startedAt >= condition.ticks;
        }

        default:
            return false;
    }
}

// ===== ACTION EXECUTION =====
export function executeAction(world: WorldState, action: LessonAction): WorldState {
    const payload = action.payload;

    switch (action.type) {
        case 'spawn_node': {
            const id = payload.id as string;
            const type = payload.type as NodeType;
            const x = payload.x as number;
            const y = payload.y as number;
            const label = payload.label as string;

            const node = createDefaultNode(id, type, { x, y });
            node.label = label || id;
            node.status = (payload.status as typeof node.status) || 'idle';
            if (payload.ip) node.ip = payload.ip as string;
            node.mac = `AA:BB:CC:${id.slice(0, 2).toUpperCase()}:DD:EE`;

            const newNodes = new Map(world.nodes);
            newNodes.set(id, node);

            return {
                ...world,
                nodes: newNodes,
                logs: [...world.logs, {
                    id: generateId('log', world.seed, world.time),
                    time: world.time,
                    type: 'system',
                    message: `Lesson: ${label || id} appeared`,
                    nodeIds: [id]
                }]
            };
        }

        case 'remove_node': {
            const id = payload.id as string;
            const newNodes = new Map(world.nodes);
            newNodes.delete(id);

            // Remove associated links
            const newLinks = new Map(world.links);
            for (const [linkId, link] of newLinks) {
                if (link.from === id || link.to === id) {
                    newLinks.delete(linkId);
                }
            }

            return {
                ...world,
                nodes: newNodes,
                links: newLinks
            };
        }

        case 'spawn_packet': {
            const protocol = payload.protocol as PacketProtocol;
            const source = payload.source as string;
            const destination = payload.destination as string;

            // Simple path
            const path = [source];
            const sourceNode = world.nodes.get(source);
            if (sourceNode) {
                for (const conn of sourceNode.connections) {
                    const connNode = world.nodes.get(conn);
                    if (connNode && (connNode.type === 'router' || connNode.type === 'firewall')) {
                        path.push(conn);
                        break;
                    }
                }
            }
            path.push(destination);

            const packet: Packet = {
                id: generateId('lesson-pkt', world.seed, world.time),
                protocol,
                source,
                destination,
                path,
                currentHopIndex: 0,
                payload: (payload.data as Record<string, unknown>) || {},
                malicious: protocol.startsWith('ATTACK'),
                encrypted: protocol.includes('TLS') || protocol.includes('HTTPS'),
                createdAt: world.time,
                ttl: 20
            };

            return {
                ...world,
                packets: [...world.packets, packet]
            };
        }

        case 'start_attack': {
            const attackType = payload.type as AttackType;
            const origin = payload.origin as string;
            const target = payload.target as string;
            const intensity = (payload.intensity as number) || 5;

            return startAttack(world, attackType, origin, target, intensity);
        }

        case 'activate_defense': {
            const defenseType = payload.type as DefenseType;
            const target = payload.target as string;
            const config = (payload.config as Record<string, unknown>) || {};

            return activateDefense(world, defenseType, target, config);
        }

        case 'update_node': {
            const id = payload.id as string;
            const node = world.nodes.get(id);
            if (!node) return world;

            const updatedNode = { ...node };
            if (payload.status) updatedNode.status = payload.status as typeof node.status;
            if (payload.health !== undefined) updatedNode.health = payload.health as number;
            if (payload.ip) updatedNode.ip = payload.ip as string;

            const newNodes = new Map(world.nodes);
            newNodes.set(id, updatedNode);

            return { ...world, nodes: newNodes };
        }

        case 'show_message': {
            const message = payload.message as string;

            return {
                ...world,
                logs: [...world.logs, {
                    id: generateId('log', world.seed, world.time),
                    time: world.time,
                    type: 'system',
                    message: `[Lesson] ${message}`,
                    nodeIds: []
                }]
            };
        }

        default:
            return world;
    }
}

// ===== LESSON STEP PROCESSOR =====
export function processLessonStep(world: WorldState, steps: LessonStep[]): WorldState {
    const lesson = world.lesson;
    if (!lesson || lesson.paused) return world;

    const currentStep = steps[lesson.currentStepIndex];
    if (!currentStep) return world;

    let newWorld = world;

    // Check if step trigger is met (for first time in step)
    const stepJustStarted = !lesson.completedSteps.includes(currentStep.id);
    if (stepJustStarted) {
        // Execute step actions
        for (const action of currentStep.actions) {
            newWorld = executeAction(newWorld, action);
        }

        // Mark as in-progress (but not completed)
    }

    // Check completion condition
    if (evaluateCondition(newWorld, currentStep.completionCondition)) {
        // Advance to next step
        const newLessonState: LessonRuntimeState = {
            ...lesson,
            currentStepIndex: lesson.currentStepIndex + 1,
            completedSteps: [...lesson.completedSteps, currentStep.id]
        };

        const log: EventLog = {
            id: generateId('log', newWorld.seed, newWorld.time),
            time: newWorld.time,
            type: 'system',
            message: `Lesson step completed: ${currentStep.name}`,
            nodeIds: []
        };

        return {
            ...newWorld,
            lesson: newLessonState,
            logs: [...newWorld.logs, log]
        };
    }

    return newWorld;
}

// ===== LESSON INITIALIZATION =====
export function initializeLesson(
    world: WorldState,
    lessonId: string,
    initialActions: LessonAction[] = []
): WorldState {
    // Clear existing state
    let newWorld: WorldState = {
        ...world,
        nodes: new Map(),
        links: new Map(),
        packets: [],
        attacks: [],
        defenses: [],
        logs: [],
        metrics: {
            networkHealth: 100,
            threatLevel: 0,
            packetRate: 0,
            compromisedNodes: 0,
            activeConnections: 0,
            packetsInFlight: 0
        },
        lesson: {
            lessonId,
            currentStepIndex: 0,
            completedSteps: [],
            paused: false,
            startedAt: world.time
        }
    };

    // Execute initial setup actions
    for (const action of initialActions) {
        newWorld = executeAction(newWorld, action);
    }

    return {
        ...newWorld,
        logs: [...newWorld.logs, {
            id: generateId('log', newWorld.seed, newWorld.time),
            time: newWorld.time,
            type: 'system',
            message: `Lesson started: ${lessonId}`,
            nodeIds: []
        }]
    };
}

// ===== LESSON CONTROL =====
export function pauseLesson(world: WorldState): WorldState {
    if (!world.lesson) return world;
    return {
        ...world,
        lesson: { ...world.lesson, paused: true }
    };
}

export function resumeLesson(world: WorldState): WorldState {
    if (!world.lesson) return world;
    return {
        ...world,
        lesson: { ...world.lesson, paused: false }
    };
}

export function resetLesson(world: WorldState): WorldState {
    if (!world.lesson) return world;
    return {
        ...world,
        lesson: {
            ...world.lesson,
            currentStepIndex: 0,
            completedSteps: [],
            startedAt: world.time
        }
    };
}

// Metrics Engine - Calculates network health, threat level, and other metrics
// Pure functions that observe world state

import { WorldState, WorldMetrics } from './world-state';

// ===== METRICS CALCULATION =====
export function calculateMetrics(world: WorldState): WorldMetrics {
    const nodes = Array.from(world.nodes.values());

    // Count node states
    const overloadedNodes = nodes.filter(n => n.status === 'overloaded').length;
    const infectedNodes = nodes.filter(n => n.status === 'infected').length;
    const compromisedNodes = nodes.filter(n => n.status === 'compromised').length;
    const quarantinedNodes = nodes.filter(n => n.status === 'quarantined').length;
    const activeNodes = nodes.filter(n =>
        n.status === 'active' || n.status === 'idle'
    ).length;

    // Calculate network health
    // Each overloaded node = -10, infected = -15, compromised = -20, quarantined = -5
    const totalNodes = nodes.length || 1;
    const healthPenalty =
        (overloadedNodes * 10) +
        (infectedNodes * 15) +
        (compromisedNodes * 20) +
        (quarantinedNodes * 5);

    const networkHealth = Math.max(0, Math.min(100, 100 - healthPenalty));

    // Calculate threat level based on active attacks
    const activeAttacks = world.attacks.filter(a =>
        a.phase === 'active' || a.phase === 'launching'
    );

    const attackThreat = activeAttacks.reduce((sum, attack) => {
        return sum + (attack.intensity * 5);
    }, 0);

    // Add threat from malicious packets
    const maliciousPackets = world.packets.filter(p => p.malicious).length;
    const packetThreat = Math.min(30, maliciousPackets * 2);

    const threatLevel = Math.min(100, attackThreat + packetThreat);

    // Calculate packet rate
    const packetRate = world.packets.length;

    // Count active connections
    const activeConnections = Array.from(world.links.values())
        .filter(l => !l.blocked).length;

    return {
        networkHealth,
        threatLevel,
        packetRate,
        compromisedNodes: compromisedNodes + infectedNodes,
        activeConnections,
        packetsInFlight: world.packets.length
    };
}

// ===== PHASE DETERMINATION =====
export function determineWorldPhase(world: WorldState): WorldState['phase'] {
    const metrics = world.metrics;
    const hasActiveAttacks = world.attacks.some(a =>
        a.phase === 'active' || a.phase === 'launching'
    );
    const hasActiveDefenses = world.defenses.length > 0;

    // Check for boot phase
    const allNodesBooting = Array.from(world.nodes.values())
        .every(n => n.status === 'offline' || n.status === 'booting');
    if (allNodesBooting && world.nodes.size > 0) {
        return 'boot';
    }

    // Check for connecting phase
    const nodesConnecting = Array.from(world.nodes.values())
        .some(n => !n.ip && n.status !== 'offline');
    if (nodesConnecting) {
        return 'connecting';
    }

    // Check for compromised state
    if (metrics.networkHealth < 30 || metrics.compromisedNodes > world.nodes.size / 2) {
        return 'compromised';
    }

    // Check for attack/defense states
    if (hasActiveAttacks && hasActiveDefenses) {
        return 'defending';
    }
    if (hasActiveAttacks) {
        return 'under_attack';
    }

    // Check for secured state (after successful defense)
    if (world.phase === 'defending' && !hasActiveAttacks) {
        return 'secured';
    }

    // Default online state
    if (world.nodes.size > 0) {
        return 'online';
    }

    return 'idle';
}

// ===== NODE HEALTH UPDATE =====
export function updateNodeHealth(world: WorldState): WorldState {
    const newNodes = new Map(world.nodes);

    for (const [id, node] of newNodes) {
        let healthChange = 0;

        // Natural recovery for non-compromised nodes
        if (node.status === 'idle' || node.status === 'active') {
            healthChange = 0.5; // Slow recovery
        }

        // Damage from overload
        if (node.status === 'overloaded') {
            healthChange = -1;
        }

        // Damage from infection
        if (node.status === 'infected') {
            healthChange = -0.5;
        }

        // Update health
        const newHealth = Math.max(0, Math.min(100, node.health + healthChange));

        // Status changes based on health
        let newStatus = node.status;
        if (newHealth <= 0 && node.status !== 'quarantined') {
            newStatus = 'compromised';
        } else if (newHealth > 50 && node.status === 'overloaded') {
            newStatus = 'active';
        }

        if (newHealth !== node.health || newStatus !== node.status) {
            newNodes.set(id, {
                ...node,
                health: newHealth,
                status: newStatus
            });
        }
    }

    return {
        ...world,
        nodes: newNodes
    };
}

// ===== LINK LOAD CALCULATION =====
export function updateLinkLoads(world: WorldState): WorldState {
    const newLinks = new Map(world.links);

    // Reset all link loads
    for (const [id, link] of newLinks) {
        newLinks.set(id, { ...link, currentLoad: 0 });
    }

    // Count packets on each link
    for (const packet of world.packets) {
        const currentNode = packet.path[packet.currentHopIndex];
        const nextNode = packet.path[packet.currentHopIndex + 1];

        if (currentNode && nextNode) {
            // Find the link
            for (const [id, link] of newLinks) {
                if ((link.from === currentNode && link.to === nextNode) ||
                    (link.to === currentNode && link.from === nextNode)) {
                    newLinks.set(id, { ...link, currentLoad: link.currentLoad + 1 });
                    break;
                }
            }
        }
    }

    return {
        ...world,
        links: newLinks
    };
}

// Protocol Engine - Handles DHCP, ARP, DNS, TCP, TLS simulation logic
// Pure functions that process packets and update world state

import {
    WorldState,
    Packet,
    PacketProtocol,
    Node,
    EventLog
} from './world-state';

// Deterministic ID generator
function generateId(prefix: string, seed: number, counter: number): string {
    return `${prefix}-${seed}-${counter}`;
}

// ===== DHCP PROTOCOL =====
export function handleDHCPDiscover(world: WorldState, packet: Packet): WorldState {
    const sourceNode = world.nodes.get(packet.source);
    const destNode = world.nodes.get(packet.destination);

    if (!sourceNode || !destNode || destNode.type !== 'router') {
        return world;
    }

    // Router responds with DHCP_OFFER
    const offerPacket: Packet = {
        id: generateId('dhcp-offer', world.seed, world.time),
        protocol: 'DHCP_OFFER',
        source: packet.destination,
        destination: packet.source,
        path: [packet.destination, packet.source],
        currentHopIndex: 0,
        payload: {
            offeredIP: `192.168.1.${10 + world.nodes.size}`,
            gateway: '192.168.1.1',
            dns: '8.8.8.8',
            leaseTime: 86400
        },
        malicious: false,
        encrypted: false,
        createdAt: world.time,
        ttl: 10
    };

    const newPackets = [...world.packets, offerPacket];
    const log: EventLog = {
        id: generateId('log', world.seed, world.time),
        time: world.time,
        type: 'protocol',
        message: `DHCP: Router offering IP ${offerPacket.payload.offeredIP} to ${sourceNode.label}`,
        nodeIds: [packet.source, packet.destination]
    };

    return {
        ...world,
        packets: newPackets,
        logs: [...world.logs, log]
    };
}

export function handleDHCPOffer(world: WorldState, packet: Packet): WorldState {
    const destNode = world.nodes.get(packet.destination);
    if (!destNode) return world;

    // Client sends DHCP_REQUEST
    const requestPacket: Packet = {
        id: generateId('dhcp-request', world.seed, world.time),
        protocol: 'DHCP_REQUEST',
        source: packet.destination,
        destination: packet.source,
        path: [packet.destination, packet.source],
        currentHopIndex: 0,
        payload: {
            requestedIP: packet.payload.offeredIP
        },
        malicious: false,
        encrypted: false,
        createdAt: world.time,
        ttl: 10
    };

    const log: EventLog = {
        id: generateId('log', world.seed, world.time),
        time: world.time,
        type: 'protocol',
        message: `DHCP: ${destNode.label} requesting IP ${packet.payload.offeredIP}`,
        nodeIds: [packet.destination, packet.source]
    };

    return {
        ...world,
        packets: [...world.packets, requestPacket],
        logs: [...world.logs, log]
    };
}

